(window.STORIES=window.STORIES||[]).push(...[{"n": 131, "l": "الجزء 105 | أحداث السنه السادسه من الهجرة | تفسير آيات حادثة الإفك | القدر الكوني والقدر الشرعي", "u": "", "t": "تفسير  ايات سورة النور  الي برأت ستنا عائشه \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وخمسة\n#أحداث_السنة_السادسة_من_الهجرة\n#تفسير_آيات_حادثة_الإفك\n#القدر_الكوني_والقدر_الشرعي\nاتكلمنا المرة إللي فاتت عن نزول الأيات إللي برّأت السيدة عائشة من إللي اتقال عليها كذبا وبهتانا إنها وقعت في الفاحشة،\nوشرحنا أول آية:\n\"إِنَّ الَّذِينَ جَاءُوا بِالْإِفْكِ عُصْبَةٌ مِّنكُمْ ۚ لَا تَحْسَبُوهُ شَرًّا لَّكُم ۖ بَلْ هُوَ خَيْرٌ لَّكُمْ ۚ لِكُلِّ امْرِئٍ مِّنْهُم مَّا اكْتَسَبَ مِنَ الْإِثْمِ ۚ وَالَّذِي تَوَلَّىٰ كِبْرَهُ مِنْهُمْ لَهُ عَذَابٌ عَظِيمٌ \"\nووقفنا عند سؤال مهم وهو: \nإزاي فتنة زي دي يكون خير لرسول الله ﷺ والصحابة وللسيدة عائشة، وخصوصا إن ربنا مقلش إن فيه خير لكم، لأ ده قال إنه خير ..على الإطلاق كده،\nفاحنا عشان نفهم إزاي الفتنة دي أو أي فتنة تانية أو أي ابتلاء تاني بيبقى خير، زي مثلا وقوع الظلم والسجن والقتل في الأرض وغيرها من الابتلاءات،\nمحتاجين نفهم يعني إيه قَدَر شرعي و قَدَر كوني\nالقدر الشرعي: \nأمور شرعية ربنا بيحبها ويرضاها ويريدها أمر بها عباده  وممكن ينفذوها وممكن لأ، زي لما ربنا أمر أبو جهل بالإيمان به وأبو جهل رفض، وزي لما ربنا يأمرنا بالصلاة وناس تصلي وناس متصليش وهكذا،\nفالقدر الشرعي يختص بكل ما يحبه الله ويرضاه فقط\nأما القدر الكوني فبيدخل فيه ما يحبه الله ويرضاه وما لا يحبه الله ويرضاه،\nيعني في أمور بتحصل بقدر الله لا يحبها ولا يرضاها لكن يسمح إنها تحصل لحكمة يعلمها وللخير إللي هيحصل بسبب الحدث ده،\nزي خلق إبليس مثلا، هو مش إبليس ده سبب مصائب ووقوع الناس في معاصي كثيرة وكبائر وشرك بالله\nلكن برده بسبب الأمور السيئة دي بتحصل أمور خير كثيرة زي التوبة والاستغفار والمجاهدة وغيرها من الطاعات،\nوكمان زي حادثة الإفك، ربنا لا يحب ولا يرضى إن رسول الله ﷺ وهو أحب الخلق إلى الله إنه يُتهم في عرضه، ومع ذلك ربنا قدّر عليه الابتلاء العظيم ده لحكمة وفوائد لا يعلمها جميعا إلا الله\nفلو نظرنا للقدر الكوني من ناحية القدر الشرعي هنرتاح جدا ويبقى عندنا ثقة تامة في الله،\nيعني لو كل واحد فينا لما يحصل له أي ابتلاء وده قدر كوني يحط نفسه مكان رسول الله ﷺ ويفكر من ناحية القدر الشرعي وإن ربنا له حكمة في كل أفعاله،\nورسول الله ﷺ وهو أحب الخلق إلى الله حصل معاه كده فما بالنا باللي أقل منه\nفمش معنى إن ربنا بيقدّر علينا ابتلاء قدري كوني سواء مرض بقى أو قتل أو ظلم يبقى ربنا راضي إن الابتلاء ده يحصل وبيحب يشوفنا متضايقين وزعلانين،\nلأ، لكن هو يريد لنا الخير والفوائد والدروس والعبر إللي هتحصل لنا ونتعلمها من وراء الابتلاء\nتعالوا كده نشوف بعض الخير إللي ربنا قال عليه باختصار:\n◇رفع شأن السيدة عائشة رضي الله عنها في الدنيا بإنزال فيها آيات تتلى إلى يوم القيامة، وكمان صحيفة حسناتها مستمرة حتى بعد موتها بسبب اتهام الروافض لها بأنها فعلت الفاحشة حتى بعد ما القرآن برأها\nوفي الآخرة رفع درجتها في الجنة وكمان رفع شأن رسول الله ﷺ وأبو بكر وأم رومان أم السيدة عائشة، وصفوان بن المعطل رضي الله عنهم أجمعين لأن الابتلاء للأنبياء والصالحين رفع للدرجات.\n◇ تدريب المؤمنين بطريقة عملية على إن محدش يقول كلمة ولا يتهم حد بالباطل بدون دليل قاطع وخاصة في الأعراض،\nوإن كلمة واحدة كافية إنها تهدم أمة الإسلام وتفرق بينهم،\nواحنا شوفنا إللي حصل بين الأوس والخزرج.\n◇تعليم المسلمين التفاؤل\nربنا بيعلم المسلمين إن في عز الأزمة إللي انتم فيها شوفوا الخير إللي هييجي من وراء الأزمة دي،\nلأن أعظم ما يهوّن المصائب في قلوب الناس تعظيم الله عز وجل، وضعف التفاؤل أثر من آثار سوء الظن بالله،\nتخيلوا لو نظرنا لكل ابتلاء بيحصل لنا على إنه خير من الله وأحسنّا الظن بالله حالنا هيبقى عامل إزاي بدل التشاؤم واليأس والقنوط وسوء الظن بالله إللي للأسف ناس كثير عايشين فيه\n\" ذَٰلِكُمْ ظَنُّكُمُ الَّذِي ظَنَنتُم بِرَبِّكُمْ أَرْدَاكُمْ فَأَصْبَحْتُم مِّنَ الْخَاسِرِينَ \"\n◇فضح المنافقين وأنهم العدو الرئيسي للمؤمنين وتوضيح خطرهم عشان المسلمين ميسمعوش لكلامهم تاني.\n\"هُمُ الْعَدُوُّ فَاحْذَرْهُمْ ۚ قَاتَلَهُمُ اللَّهُ ۖ أَنَّىٰ يُؤْفَكُونَ\"\nلما نتدبر كلام ربنا: \"لِكُلِّ امْرِئٍ مِّنْهُم مَّا اكْتَسَبَ مِنَ الْإِثْمِ\"\nهنلاقي إن ربنا بيعلمنا العدل، يعني مع إن المجموعة دي اتكلمت في عرض السيدة عائشة بس كل واحد له نصيب من الإثم، مش كلهم زي بعض، كل واحد هيتحاسب على أد الكلام إللي قاله،\nربنا بيعلمنا إننا نعامل كل واحد على حسب خطأه، حتى عبد الله بن أبي بن سلول ربنا قال إن له عذاب عظيم بسبب إنه أكثر واحد نشر الإفك والكذب وهو السبب فيه أصلا،\nودائما قادة الشر عذابهم بيكون أكبر من الناس إللي بتتبعهم،\nزي فرعون كده،\n\"يَقْدُمُ قَوْمَهُ يَوْمَ الْقِيَامَةِ فَأَوْرَدَهُمُ النَّارَ\"\nبعد ما ربنا قال إن الكلام إللي المنافقين نقلوه ده كان كذب، وجه المؤمنين إزاي يتصرفوا في المواقف إللي زي دي وقال :\n\"لَوْلا إِذْ سَمِعْتُمُوهُ ظَنَّ الْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بِأَنْفُسِهِمْ خَيْرًا\"\nوالآية دي اتكلمنا عنها بالتفصيل المرة إللي فاتت، \nوهي الآية إللي بتؤيد فعل أبو أيوب الأنصاري وزوجته رضي الله عنهما،\nوهو ده الفعل الصحيح مادام مفيش دليل، وإلا يجيبوا أربعة شهداء يشهدوا على كلامهم، ولو مجابوش الشهداء يبقى هم الكاذبين،\n\"لَّوْلَا جَاءُوا عَلَيْهِ بِأَرْبَعَةِ شُهَدَاءَ ۚ فَإِذْ لَمْ يَأْتُوا بِالشُّهَدَاءِ فَأُولَٰئِكَ عِندَ اللَّهِ هُمُ الْكَاذِبُونَ \"\n☆السؤال بقى، لو مجابوش أربعة شهداء يبقى إيه حكمهم\nمن يتهم امرأة في عرضها وإنها فعلت الفاحشة أو يتهم رجل بدون ما يأتي بأربعة شهداء يشهدوا إنهم شافوا المرأة أو الرجل بيعملوا الفاحشة، يُجلد ثمانين جلدة\nوالمقصود إن الأربعة يشوفوا بعينهم فرج الرجل داخل في فرج المرأة، \nويوصفوا إللي شافوه وصف دقيق مش إنهم يوصفوا المشهد العام لاجتماع الرجل والمرأة ولو كانا عاريَيْن أو يقولوا شوفناه بيزني وخلاص،  \nولازم الشهداء يكونوا أربعة رجال مسلمين أحرار عدول، \nيعني لو ثلاثة تحققت فيهم الشروط ووصفوا فعلا إللي حصل وإنه زنا لكن مفيش شاهد رابع أو حتى الشاهد الرابع مشفش كويس أو شهادته خالفت شهادة الثلاثة،\nالثلاثة دول يتجلدوا ثمانين جلدة\n☆موضوع كشف الزنا مُعقد ويكاد يكون مستحيل صح \nوده من حفظ ربنا لأعراض الناس، عشان مش أي حد يقول أي حاجة وخلاص ويعتدي على أعراض المسلمين\nفالصحابة إللي صرّحوا بوقوع السيدة عائشة في الفاحشة جُلدوا ثمانين جلدة، زي حسان بن ثابت ومسطح بن أَثاثة وحِمْنة بنت جحش،\nفالحد ده تطهير لهم مع توبتهم، حسان بن ثابت ومسطح  رضي الله عنهما كانا من أهل بدر، وقلنا إن أهل بدر لهم مكانة خاصة، لكن ده لا يمنع من إقامة الحدود عليهم،\nوخدوا بالكم إن الكلام ده كان قبل نزول القرآن ببراءة عائشة رضي الله عنها، \nلكن أي حد يتكلم في عرض السيدة عائشة بعد نزول القرآن وهو عارف بآيات القرآن فهو كافر لتكذيبه صريح القرآن\nفهم تابوا ورسول الله ﷺ أقام عليهم الحد وبكده خلاص انتهى الموضوع والتائب من الذنب كمن لا ذنب له،\nوحسان رضي الله عنه اعتذر عن الكلام إللي قاله وقال قصيدته المشهورة في مدح السيدة عائشة :\nحصـانٌ رزانٌ مـا تُزنُّ بريبةٍ\nوتصبح غرثى من لحوم الغوافلِ\nوهنا ربنا قال لهم في الآية إللي بعدها :\n\"وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ فِي الدُّنْيَا وَالْآخِرَةِ لَمَسَّكُمْ فِي مَا أَفَضْتُمْ فِيهِ عَذَابٌ عَظِيمٌ\"\nيعني من رحمة ربنا وفضله إنه تقبل توبتهم وعفا عنهم وده لأنهم مؤمنين صادقي الإيمان وإلا فكان هيصيبهم في الدنيا والآخرة عذاب عظيم،\nوهو سبحانه لم يعذبهم لأنه أراد إن المؤمنين يأخذوا العبرة والعظة من الحادثة دي، فحادثة الإفك وسيلة توضيحية للمؤمنين إزاي يحفظوا أعراض بعض ومحدش يتكلم بدون دليل،\n فمادم الإنسان تاب وأصلح خلاص مينفعش كل شوية نقعد نفكره بذنبه ونعيره به مثلا وخصوصا لو كان من أهل الفضل والصلاح بس وقع في ذَلة،\nورسول الله ﷺ مقعدش يعاتب حسان أو غيره كل شوية إنهم تكلموا في عرضه بعد ما تابوا وهو القائل ﷺ:\n\" لا تُؤذُوا عبادَ اللهِ ولا تُعيِّروهم ولا تطلُبوا عوراتِهم\"\nأما المنافقين فمش هيدخلوا في الآية دي لأن معندهمش أعمال صالحة ولم يتوبوا من كلامهم عن السيدة عائشة فجزاؤهم مستنيهم في الآخرة،\nوعاتب الله المؤمنين إنهم قعدوا ينقلوا الكلام بينهم وبيتكلموا وهم ميعرفوش أي حاجة ومفكرين الموضوع بسيط وهو عظيم جدا عند ربنا،\nوالمفروض إنهم كانوا يُكذبوا الكلام وينفوه وميتكلموش فيه \nويُنزهوا الله عز وجل إنه يَرضى لرسوله ﷺ إنه يتزوج من امرأة هتقع فيها فاحشة،  \n\"إِذْ تَلَقَّوْنَهُ بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِكُم مَّا لَيْسَ لَكُم بِهِ عِلْمٌ وَتَحْسَبُونَهُ هَيِّنًا وَهُوَ عِندَ اللَّهِ عَظِيمٌ ۩\nوَلَوْلَا إِذْ سَمِعْتُمُوهُ قُلْتُم مَّا يَكُونُ لَنَا أَن نَّتَكَلَّمَ بِهَٰذَا سُبْحَانَكَ هَٰذَا بُهْتَانٌ عَظِيمٌ \"\nونهاهم إنهم يقعوا في حاجة زي كده مرة ثانية في المستقبل إذا كانوا بيؤمنوا بالله وشرعه وفي قلوبهم تعظيم لله ولرسوله، \n\"يَعِظُكُمُ اللَّهُ أَن تَعُودُوا لِمِثْلِهِ أَبَدًا إِن كُنتُم مُّؤْمِنِينَ \"\nوده توضيح لأحكام الله القدرية والأحكام الشرعية،\n\"وَيُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ ۚ وَاللَّهُ عَلِيمٌ حَكِيمٌ\"\nوتوعد الله الناس إللي بيحبوا انتشار الفواحش بين المؤمنين عن طريق نشرها وإظهارها بالعذاب في الدنيا عن طريق الحد وفي الآخرة بعذاب الآخرة، عشان كده لازم المؤمن يرد العلم إلى الله وهنا هيفلح\n\"إِنَّ الَّذِينَ يُحِبُّونَ أَن تَشِيعَ الْفَاحِشَةُ فِي الَّذِينَ آمَنُوا لَهُمْ عَذَابٌ أَلِيمٌ فِي الدُّنْيَا وَالْآخِرَةِ ۚ وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ\"\n☆ملحوظة : \nعبد الله بن أبي بن سلول لم يُقم عليه الحد فلم يُجلد مع الناس إللي اتجلدوا، وده بسبب:\n◇ إنه لم يُصرّح بإن السيدة عائشة وقعت في الزنا، يعني\n كان الكلام كله تعريض وهو خبيث وعنده خبرة في الكلام مع الناس فعرف إزاي يوقع الناس في الغلط ويطلع هو منها،\n فالناس بقت تنقل الكلام على حسب ما فهمت، وده يزود كلمة وده يزود كلمة لحد ما بقى في تصريح بالزنا من المؤمنين أنفسهم، \n◇أو لأن مفيش شهود يشهدوا عليه إنه صرح بإن السيدة عائشة وقعت في الفاحشة.\n☆ممكن حد يسأل ويقول طيب ماهو ربنا قال عنه إنه تولى كِبره وإنه له عذاب عظيم، وده كلام واضح جدا إن هو السبب أصلا في الموضوع كله\nمن حكمة ربنا إنه جعل الأحكام تكون بشهادة الشهود والأدلة،\nيعني ولله المثل الأعلى في قاعدة في الشرع بتقول:\n《 لا يقضي القاضي بعلمه》\nيعني لو قاضي شاف واحد بيسرق وجاله المحكمة ومفيش شهود على السارق ده غير القاضي، مينفعش القاضي يحكم عليه بحكم إنه شافه؛ لأنه لا يحكم بعلمه لازم شهود،\nممكن ساعتها القاضي يحول القضية لقاضي تاني وساعتها يقدر يشهد على أساس إنه بقى شاهد،\nفنفس المعنى في أمور الحدود، لازم شهود عشان إقامة الحد فربنا جعل الحكم فيما يظهر للناس،\nودي قاعدة عامة تشريعية مش خاصة بزمن رسول الله ﷺ، يعني لو رسول الله ﷺ أقام الحد على عبد الله بن أبي بن سلول بعلم الله، الناس إللي هتيجي بعد رسول الله ﷺ هيقلدوه إزاي والوحي خلاص انقطع\nفكان لازم قاعدة عامة للناس من بعده ﷺ وهي إننا ناخد بالظاهر ونعتمد على الشهود زي ما ربنا قال\n☆إزاي بقى نربط قصة الإفك بالواقع بتاعنا\nشوفوا، \nالهدف الرئيسي إللي خلى المنافقين يتكلموا في السيدة عائشة إنهم كانوا عايزين يطعنوا في رسول الله ﷺ نفسه، والطعن في رسول الله ﷺ هو طعن في الدين نفسه لأنه رسول من عند الله،\nودي قاعدة عند المنافقين مستمرة من عهد رسول الله ﷺ لحد عصرنا دلوقتي وللأسف وقع فيها بعض طلبة العلم وهي قاعدة ضرب الرموز\nهمّ الصحابة بياخدوا دينهم من مين؟\nمش من رسول الله ﷺ، طيب تخيلوا لما صورته تتشوه في قلوب الصحابة أو على الأقل يدخل الشك في قلوبهم من ناحية رسول الله ﷺ، النتيجة هتكون إيه؟\nطبعا النتيجة هتكون ضياع الثقة بين الصحابة وبين رسول الله ﷺ و بالتالي ضياع الدين\nلكن من رحمة ربنا بالصحابة إن محصلتش القصة دي، وربنا كشف المنافقين قصاد الصحابة ورد كيدهم واتفضحوا،\nوهو ده بقى إللي بيحصل في عصرنا بالضبط\nلو تفتكروا الكم سنة الأخيرة كل شوية يطلع كلام يطعن في  حد من المشايخ أو العلماء الربانيين إللي بقالهم سنين طويلة عايشين بيخدموا دين ربنا ، \nوده لأن أعداء الدين عايزين يشوهوا صورة العلماء باستمرار ولما يشوهوها الناس مش هتثق في كلامهم بعد كده، وبالتالي مش هياخدوا منهم الدين، والدين محتاج له علماء يشرحوه، \nطيب هياخدوا دينهم من مين دلوقتي\nإما هيبعدوا عن الدين كله، أو هياخدوا دينهم من الناس إللي بتتبع أهواءها أو معندهمش علم وبيضلوا الناس بفتاويهم،\nوبكده الناس دينها يضيع وهو إللي المنافقين وأعداء الدين عايزينه\nوالمشكلة إن الناس تنشر الكلام ده وتشتم المشايخ والعلماء ولو جينا نسألهم طب يا جماعة جبتم الكلام منين ولّا إيه الدليل ولّا انتم تعرفوا إيه عن المواضيع أصلا ،\nهيقولوا أصل هو قال كذا وكان المفروض يقول كذا، أو هو عمل كذا وكان المفروض يعمل كذا وهو أصلا منافق احنا سمعنا عنه كذا وكذا أو غيرها وغيرها من الحجج،\nطيب هو فين القرآن في حياتنا يا جماعة\nفين لولا إذ سمعتموه ظن المؤمنون والمؤمنات بأنفسهم خيرا، يعني أنا هكون أغير على الدين من الشيخ ولّا العالم إللي أفنى عمره كله في تعليم الناس الدين والدفاع عنه؟!!\nفين لولا إذ سمعتموه قلتم ما يكون لنا أن نتكلم بهذا؟!!\nهو احنا عارفين كل حاجة، احنا حتى قعدنا مع الشيخ ولا العالم ده وفهمنا منه،\nإللي سكت من الصحابة ومتكلمش عصم نفسه، ولما نزلت الآيات مخسرش حاجة بالعكس ده نجى نفسه من الحد،\nوإللي اتكلم أخطأ وأُقيم عليه الحد،\nطيب ليه احنا منعملش زي الصحابة إللي سكتوا وننجي نفسنا من إننا نيجي يوم القيامة نلاقي حسناتنا أخذها غيرنا،\nيا جماعة آيات حادثة الإفك مش خاصة بحادثة الإفك فقط ولا هي خاصة بزمن رسول الله ﷺ، \nالأحداث دي بتتكرر سواء على المستوى العام للأمة أو المستوى الخاص بحياتنا،\nكم مرة وصل لنا أخبار أو كلام مش كويس عن ناس نعرفهم، مش لازم يكون الكلام حاجة كبيرة زي فعل الفاحشة، لأ، أي كلام بيقدح فيهم،\nساعتها رد فعلنا بيكون إيه؟ هل بناخد الكلام ونقعد ننقله وننشره ،ولّا بنحسن الظن ونعمل زي أبو أيوب الأنصاري رضي الله عنه، \nأو على الأقل نسكت ومنجبش سيرة الناس وبكده يبقى خرجنا خالص من أي شبهة وحافظنا على حسناتنا\nعلى فكرة أنا بركز على إننا نصلح نفسنا ونمسك ألستنا، عشان محدش يقول أصل هم فعلا كده ويستاهلوا و...و...\n المشايخ والعلماء أو حتى الناس إللي وصل لنا عنهم كلام مش كويس واحنا اتكلمنا فيهم احنا كمان وطلعوا يوم القيامة مظلومين زي السيدة عائشة كده، هتبقى مصيبة ما بعدها مصيبة \nلكن لو العكس بقى، والتزمنا بقول رسول الله ﷺ:\n\"من كان يؤمن بالله واليوم الآخر فليقل خيرا أو ليصمت\"\nفاحنا أكيد هنبقى كسبانين ساعتها وهنبقى سعداء واحنا شايفين غيرنا حسناته ضاعت واحنا محافظين على حسناتنا\nبعد ما ظهرت براءة السيدة عائشة، غضب أبو بكر الصديق رضي الله عنه من مِسطح وأقسم إنه مش هينفق عليه من ماله، \nمسطح كان ابن بنت خالة أبو بكر، وكان فقير مكنش عنده مال فأبو بكر كان بيساعده بالمال،\nفبلغة عصرنا إللي بيعمل كده الناس بتقول عليه ده مطمرش فيه المعروف وناكر للجميل، والناس بتزهد في فعل الخير بسبب إساءة من أحسنوا إليهم،\nيعني كان المفروض إن مسطح يكون هو أول واحد يدافع عن السيدة عائشة باعتبار إن أبوها بيساعده حتى لو مجاملة،\nأو على الأقل يسكت،\nولكن حصل العكس وهو إنه تكلم فيها رضي الله عنها، وكان رد فعل أبي بكر الصديق إنه منع عنه النفقة،\nفنزل القرآن يقول لأبي بكر ولكل من كان في موقف أبي بكر إنه يعفو ويصفح عن مسطح ويرجع النفقة عليه مرة ثانية، فزي مانتم تحبوا عفو الله وغفرانه لذنوبكم انتم كمان اغفروا وسامحوا للي أقل منكم، وإللي هيعمل كده هيكون جزاؤه الغفران، \n\"وَلَا يَأْتَلِ أُولُو الْفَضْلِ مِنكُمْ وَالسَّعَةِ أَن يُؤْتُوا أُولِي الْقُرْبَىٰ وَالْمَسَاكِينَ وَالْمُهَاجِرِينَ فِي سَبِيلِ اللَّهِ ۖ \nوَلْيَعْفُوا وَلْيَصْفَحُوا ۗ أَلَا تُحِبُّونَ أَن يَغْفِرَ اللَّهُ لَكُمْ ۗ وَاللَّهُ غَفُورٌ رَّحِيمٌ\"\nوخصوصا إن مسطح كان خلاص أُقيم عليه الحد وتاب، فربنا أراد إنه يصفي النفوس من الفتنة إللي حصلت دي ،\nفلما سمع أبو بكر الآية قال:\nبلى واللّه إنا نحب أن تغفر لنا يا ربنا، وبعدين رجع النفقة تاني على مسطح رضي الله عنهم أجمعين.\nعلى الرغم من إن الأحداث كانت صعبة والأزمة في المدينة كانت شديدة بسبب حادثة الإفك إلا إن حركة الجهاد لم تتوقف، هنشوف إن شاء الله الجزء الجاي السرايا إللي أخرجها رسول الله ﷺ في نفس وقت حادثة الإفك"}, {"n": 132, "l": "الجزء 106 | أحداث السنه السادسه من الهجرة | برصيصا العابد", "u": "", "t": "حرفيآ الشيطان بيعرف يخطط عشان تسمعو كلامو وهوا كدا كدا فاضي بس مين بقى الي مش يستسلم ليه\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وستة\n#أحداث_السنة_السادسة_من_الهجرة\n#برصيصا_العابد\nقبل مانبتدي الجزء بتاع النهاردة عايز أقول ملحوظة للأمانة العلمية \n◇العلماء اختلفوا في وقت غزوة بني المصطلق إللي حصل بعدها حادثة الإفك كانت امتى بالضبط\nفي علماء قالوا إنها كانت في السنة الخامسة من الهجرة قبل غزوة الأحزاب أصلا، وفي علماء قالوا إنها كانت في السنة السادسة من الهجرة زي ما أنا شرحت،\nوأنا اخترت الرأي إللي بيقول إنها كانت في السنة السادسة لأنه أقرب إلى المنطق،\nلأن السيدة عائشة قالت إن صفوان كان يعرفها قبل فرض الحجاب ولما شافته غطت وجهها، \nوالحجاب اتفرض بعد غزوة بني قريظة في يوم زواج رسول الله ﷺ من السيدة زينب رضي الله عنها في ذي القعدة سنة خمسة هجريا قولا واحدا بدون خلاف،\nفإزاي بقى تكون حادثة الإفك قبل غزوة الأحزاب\nأنا قلت لكم المعلومة دي عشان لو سمعتم الرأي إللي بيقول إن حادثة الإفك كانت في السنة الخامسة متستغربوش\n◇وبرده العلماء اختلفوا في قصة العقد إللي وقع من السيدة عائشة وكان سبب في نزول آية التيمم هل كان في غزوة بني المصطلق زي ما شرحت ولّا كان في غزوة تانية،\nوأنا اخترت القول إللي بيقول إنه كان في نفس غزوة بني المصطلق، يعني العقد وقع من السيدة عائشة مرتين في نفس الغزوة، \nفالموضوع مش هيفرق كتير هو كان في نفس الغزوة ولّا في غيرها، يعني ممكن تاخدوا بالرأي إللي يناسبكم، أهم حاجة عرفنا أحداث نزول آية التيمم\nأنا محبتش أدخل في تفاصيل الإختلاف بين العلماء عشان محدش يتلخبط \nندخل في شرح الجزء بتاع النهاردة\nقلنا المرة إللي فاتت إن رسول الله ﷺ موقّفش حركة الجهاد على الرغم من إن الأحداث كانت شديدة وصعبة عليه ﷺ وعلى الصحابة،\nوده علّم الصحابة إنهم يفصلوا بين حياتهم الشخصية وحزنهم وابتلاءاتهم وبين الواجبات المفروضة عليهم، \nيعني مهما كان الإنسان في ابتلاءات أو مهموم أو حزين ده مش مبرر إنه يعطل حياته وخصوصا خدمته للدين،\nوده إللي المفروض احنا كمان نتعلمه\nفي ناس حياتها بتقف حرفيا لما تتعرض لابتلاء صعب شوية،\nلكن رسول الله ﷺ كان غير، \nهو عارف إن الحزن أو الألم مينفعش يوقفوه عن العمل الواجب عليه، \nرسول الله ﷺ رئيس دولة كل الناس بيعادوها، واحنا مصدقنا إن الدولة الصغيرة الناشئة دي بدأت تقف على رجلها وتثبت وجودها بين العرب، \nفكان لازم يستمر في تثبيت دعائم الدولة الإسلامية وخصوصا بعد المكاسب إللي حققتها الدولة الإسلامية من بعد غزوة الأحزاب\nده غير كده لما رسول الله ﷺ يستمر على نفس منهجه في الجهاد برغم الفتن والمصائب ده فيه رسالة واضحة جدا للمنافقين وللعرب إن مفيش حاجة هتأثر فينا حتى المشاكل الداخلية هنقدر نحلها من غير ما حياتنا تقف،\nففي نفس الشهر شهر شعبان إللي حصلت فيه حادثة الإفك أخرج رسول الله ﷺ سريتين،\nالسرية الأولى كانت بقيادة عبد الرحمن بن عوف رضي الله عنه وجهز معاه سبعمائة مقاتل من الصحابة،\nوكانت مهمة السرية دي إنها تتجه لديار بني كلب في مكان اسمه دَوْمة الجَندل يعني الحصن الذي بناه دوما، وكانت بعيدة جدا عن المدينة على حدود الشام كده وهي أبعد مكان وصلت إليه الجيوش الإسلامية،\nواتسمت السرية دي باسم سرية دومة الجندل، وكان الهدف من السرية دي هو الدعوة إلى الإسلام،\nأمر رسول الله ﷺ عبد الرحمن بن عبد عوف إنه يخرج في الليل مع جيشه ووصاه بإنه يقاتل الكفار في سبيل الله،\nولا يغدر ولا يقتل أطفال\n فانطلق الجيش في وقت السّحر وكانوا معسكرين في مكان اسمه الجُرْف، \nوصلى عبد الرحمن بن عوف الفجر مع رسول الله ﷺ فاستغرب رسول الله ﷺ من وجود عبد الرحمن بن عوف معاهم مع إنه كان المفروض يكون مع الجيش وسأله ﷺ انت بتعمل إيه هنا؟!\nفقال له عبد الرحمن : أحببت يا رسول الله أن يكون آخر عهدي بك وأنا لابس لبس السفر\nوخرج بعدها عبد الرحمن ولَحق بأصحابه ومشيوا في الصحراء لحد ما وصلوا ديار بني كلب وعسكر هناك وقعد يدعوهم إلى الإسلام لمدة ثلاثة أيام،\nفي البداية رفضوا الإسلام وكانوا ناويين على قتاله، لكن في اليوم الثالث سيدهم الأصبغ بن عمرو الكلبي أسلم وكان نصرانيا،\nفأسلم من قومه ناس كثير بسبب إسلامه ومحصلش قتال وأرسل عبد الرحمن بن عوف لرسول الله ﷺ رسالة يحكي له إللي حصل وقال له إنه عايز يتزوج من القبيلة دي، \nفرسول الله ﷺرد عليه برسالة قال له فيها إنه يتزوج تُمَاضِر بنت الأصبغ  سيد القبيلة، فتزوجها عبد الرحمن ورجع بها إلى المدينة،\nالسرية الثانية إللي أخرجها رسول الله ﷺ في شهر شعبان في نفس وقت حادثة الإفك كانت سرية علي بن أبي طالب إلى ديار بني سعد في منطقة فَدَك، \nوالسبب في إخراج السرية دي إن رسول الله ﷺ عرف إن يهود خيبر برئاسة اليسير بن رَزَام بيجمعوا العرب عشان يهجموا على المدينة مرة ثانية، يعني عايزين يعيدوا الأحزاب  مرة ثانية\nفبنِي سعد بيجهزوا نفسهم عشان يتعاونوا مع اليهود للهجوم على المدينة، \nفأرسل لهم رسول الله ﷺ علي بن أبي طالب ومعاه مائة من الصحابة عشان يقاتلوهم ويفرقوا تجمعهم،\nوبكده رسول الله ﷺ قضى من البداية على تجمع كان هيهدد المدينة كلها مرة ثانية زي ما حصل في الاحزاب،\nتخيلوا بقى لو رسول الله ﷺ كان منشغل بالأحداث الداخلية من غير ما يتابع الأخبار في الجزيرة العربية ويعرف أخبار التجمعات إللي بتهدد أمن المجتمع المسلم في المدينة  النتيجة كانت هتبقى كارثية إزاي\nبعد حادثة الإفك نزلت سورة مهمة وفيها أحكام شرعية كثيرة للمسلمين بصفة عامة وللنساء بصفة خاصة وهي سورة النور\nوسورة النور ربنا بدأها بقوله :\n\"سُورَةٌ أَنزَلْنَاهَا وَفَرَضْنَاهَا وَأَنزَلْنَا فِيهَا آيَاتٍ بَيِّنَاتٍ لَّعَلَّكُمْ تَذَكَّرُونَ \" \n يعني هو ربنا مأنزلش القرآن كله \nلأ، ربنا أنزل القرآن كله ولكنه هنا خص السورة دي بالإنزال لمزيد من الإعتناء بها، يعني بيلفت نظرنا لأهمية الأحكام إللي في السورة دي\nوقال فرضناها يعني الأحكام إللي فيها فرض عليكم العمل بها وعلى إللي هييجوا من بعدكم وكلكم ملزمين بتنفيذ الأحكام دي،\nفسورة النور زي السُّور كده، إللي هيلتزم بأحكامها كأنه وضع سور مرتفع يحمي به نفسه وأهل بيته من كل شيء د ممكن يضره به لأن فيها مبادئ عظيمة منها:\n◇تعليم الناس الثقة بالله وإن المبادئ والأحكام إللي ربنا بيفرضها ربنا عليهم هي لمصلحتهم في الدنيا والآخرة وهو أعلم بهم لأنه هو من خلقهم.\n◇ تجريم عقوبتي الزنى والقذف، فاللي هيعرف العقوبة مش هيقرب من الفعل.\n◇تعليم الناس إن الأصل هو حسن الظن بالمسلم مادام مفيش دليل واضح يفيد عكس كده من خلال حادثة الإفك.\n◇ تأديب أهل البيت الواحد بأدب الاستئذان على الأسرة نفسها.\n◇ وسائل الوقاية من الجريمة، وتجنيب النفوس أسباب الإغراء والغواية؛ وده عن طريق توضيح آداب البيوت والاستئذان على أهلها، \nوالأمر بغض البصر والنهي عن إبداء الزينة لغير المحارم، والتشجيع على تزويج على الشباب ولو كانوا فقراء، فإن الله سبحانه سيغنيهم من فضله، وفيها النهي عن البغاء ووسائله.\n◇ التحذير من اتباع خطوات الشيطان، وتوضيح أن اتباع خطوات الشيطان تؤدي إلى كوارث لأن الشيطان مش هيسيب الإنسان وهيفضل يجره واحدة واحدة لحد ما يوصله للكفر زي إللي حصل مع بِرْصِيصَا العابد.\n☆مين برصيصا ده\nبرصيصا كان رجل عابد من بني إسرائيل،\nوقصته من الإسرائيليات التي لا نكذبها ولا نصدقها إللي اتكلمنا عنها في الجزء الخامس من سلسلة قصص الانبياء لو تفتكروا \nحكى علماء التفسير قصة برصيصا وهم بيفسرو قول ربنا في القرآن:\n\"كَمَثَلِ الشَّيْطَانِ إِذْ قَالَ لِلْإِنسَانِ اكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّي بَرِيءٌ مِّنكَ إِنِّي أَخَافُ اللَّهَ رَبَّ الْعَالَمِينَ \"\nبرصيصا كان أعبد أهل زمانه، عبد ربنا حوالي سبعين سنة وكان معتكف في صومعته للعبادة ومكنش بيسيبها، ولم يُذنب أي ذنب ظاهري ولم يستطع الشيطان أن يغويه ويفتنه طول الفترة دي حتى مردة الشياطين مقدروش عليه\nوالكل بيتكلم عن برصيصا العابد وعن تقواه وكان مضرب المثل في العبادة،\nوالعبادة يعني مكنش وراه غير الصيام والصلاة والذكر فقط متخيلين، لا بيقابل ناس ولا بيرفّه عن نفسه ولا غيره،\nخدوا بالكم هو كان عابد مش عالم\nالمهم كان في القرية إللي هو فيها ثلاثة إخوة وعندهم أخت واحدة، وكانوا عايزين يخرجوا للجهاد في سبيل الله،\nلكن مش عارفين هيسيبوا أختهم مع مين يكون أمين عليها ويرعاها\nفملقوش غير برصيصا العابد، لكن برصيصا قاعد في صومعته هيسبوها إزاي عنده، فقالوا هنبني جنب الصومعة بتاعته غرفة تجلس فيها أختهم ،\nراحوا كلموه وقالوا له عايزين نسيب أختنا عندك فرفض، فقعدوا يتحايلوا عليه وقالوا له احنا هنخرج للجهاد يعني عايزين نعبد الله وهي في غرفة جنب الصومعة بتاعتك،\nوانت بس مطلوب منك إنك تاخد الأكل وتحطه على باب غرفتها وحتى مش هيبقى بينكم كلام\n بس الناس هتبقى فاهمة إن في رجل بيرعى المرأة دي، فوافق برصيصا لأن الموضوع بسيط ومش هيعطله عن العبادة وكمان ده باب خير وطاعة لله،\nسافر الثلاثة إخوة وتركوا أختهم في الغرفة وكان برصيصا بيضع لها الطعام أمام باب الغرفة ويخبط عالباب ويرجع لصومعته من غير ما يكلمها كلمة واحدة ومن غير ماهي كمان تكلمه،\nواستمر الوضع كده فترة واتعود على فعل الخير الجديد ده، ومفيش أي حاجة مخالفة خالص أهه وكله تمام\nفي يوم من الأيام جاءه الشيطان ووسوس له وقال :\nانت عارف البنت دي عايشة ولّا ميتة \nولّا ممكن تكون مريضة ومحتاجة حاجة وهي متقدرش تكلم حد، واخواتها سايبينها أمانة عندك، \nهتقول لهم إيه لو جرى لها حاجة وانت كده هتضيع الأمانة، وهتقول إيه لربنا لو ضيعت الأمانة دي،\nعلى الأقل سلم عليها وهي لما ترد السلام هتعرف إنها كويسة وكل ده من وراء الباب\nوبرصيصا مكنش راضي يعمل كده، مع الأيام ومع إلحاح الشيطان أخذ برصيصا الخطوة الأولى وبقى يسلم على المرأة ، \nيعني يحط الأكل قصاد الباب ويخبط على الباب ويسلم على المرأة فقط وميكلمهاش أي كلمة تانية وهي ترد السلام وبعدين يرجع للصومعة بتاعته، واستمر الحال ده فترة من الزمن،\n\"يَا أَيّهَا الَّذِينَ آمَنُوا لَا تَتَّبِعُوا خُطُوَات الشَّيْطَان \"\nبرصيصا اتعود إنه يسلم على المرأة خلاص وبقى الموضوع طبيعي بالنسبة له، بعد فترة جاءه الشيطان يوسوس له تاني وقال له:\nالمرأة لوحدها في البيت ويمكن محتاجة لشيء ومكسوفة تكلمك واخوانها اتأخروا عليها، فاسألها بس وشوفها لو محتاجة حاجة، \nوانت رجل صالح مش هتعمل حاجة يعني ده انت بتساعدها بس، ولو انت مسألتهاش مين إللي هيسألها\nفأخذ برصيصا الخطوة إللي بعد كده، وبقى يضع الطعام ويخبط على الباب ويسلم على المرأة ويسألها : محتاجة حاجة؟\nفلو كانت محتاجة لشيء قالت له ولو مكنتش محتاجة قالت : لأ، وبعدين يرجع للصومعة يتعبد فيها لله،\n\"يَا أَيّهَا الَّذِينَ آمَنُوا لَا تَتَّبِعُوا خُطُوَات الشَّيْطَان \"\n☆كل الكلام لحد دلوقتي مفهوش أي مشكلة خالص أهه\nبرصيصا اتعود على سماع صوت البنت، والطبيعي إن إللي بيتعود على سماع الصوت بيشتاق إنه يشوف الشخص ده سواء رجل أو امرأة، فالكلام يدعو للنظر\nبرصيصا بدأ يتكلم مع البنت باستفاضة، مبقاش مجرد إنه بيسألها عن حالها وخلاص ده الكلام بقى يجيب كلام بحجة إن مفيش حد معاها يؤنسها،\nوأكيد البنت هي كمان كانت بتسرح بخيالها وتتصور إن برصيصا مهتم بيها ويا سلام بقى لو تتزوج الرجل الصالح ده،\nواستمر الوضع ده فترة من الزمن، \nماهو كل خطوة عشان تتثبت وتبقى عادي عند برصيصا محتاجة زمن والشيطان فاضي، همه كله إنه ينفذ خطته\nجاء الشيطان يوسوس لبرصيصا تاني وقال له: \nانت واقف تكلم البنت من وراء الباب والناس رايحة جاية وشايفينك، شكلك إيه قصاد الناس دلوقتي وهيقولوا عليك إيه، ادخل على البنت كلمها واطلع على طول،\nوانت رجل صالح ومستحيل تعمل حاجة تغضب ربنا\nضعف برصيصا وبقى يدخل على البنت يكلمها فقط ويخرج، \nواستمر الوضع كده والشيطان يزينها له ويزينه لها وما اختلى رجل بامرأة إلا كان الشيطان ثالثهما،\nمرة في مرة بدأ ينظر إليها، وبعدين بدأ يلمسها حتى وقع معها في الفاحشة\nرجع لصومعته خائف إزاي وقع في الكبيرة دي وهو العابد الزاهد، مبقاش يكلمها وبقى يضع لها الطعام أمام الباب ويمشي، فنادت عليه مرة وقالت له، إنها حامل،\nفخاف برصيصا من الفضيحة وهيعمل إيه، فاستغل الشيطان ضعفه ووسوس له وقال له اقتلها، ولو اخوتها سألوك عنها قل لهم إنها مرضت وجاء أجلها وماتت وانت دفنتها،\nومحدش هيشك فيك \nفأخذها برصيصا وقتلها ودفنها، بعد فترة جاء إخوة البنت وبحثوا عنها ملقوهاش، سألوا برصيصا قال لهم مرضت وماتت،\nشكروه وأكرموه على عنايته بأختهم ورجعوا للبيت،\nالشيطان بقى جاء للثلاثة إخوة في الحلم وقال لهم القصة الحقيقية وإن برصيصا زنا بأختهم وحملت وبعدين قتلها ودفنها عند صخرة معينة،\nتاني يوم لما صحيوا تكلم الأخ الأصغر وقال:\nأنا شوفت رؤيا أفزعتني\nفسألوه إخوته : ماذا رأيت\nفحكى لهم الرؤيا، فقال الأوسط :أنا كمان شوفت نفس الرؤيا\nوقال الأكبر : وأنا كمان شوفت نفس الرؤيا بتاعتكم\nفقالوا يبقى أكيد الموضوع فيه إن، خلونا نتأكد، راحوا عند الصخرة إللي شافوها في الحلم ونبشوا القبر لقوا جثة أختهم وهي مذبوحة\nراحوا لبرصيصا ونزلوه من صومعته وجروه والناس عرفت بالموضوع واتفضح أمره والناس بقت تشتمه وتضربه بقى انت العابد الزاهد وتعمل كده،\nتخيلوا حياته اتقلبت إزاي، وإحساسه كان إيه وهو مصلوب مستني حكم الإعدام وشايف نظرات الإحتقار من الناس وسامع الشتيمة، يتمنى إنه كان استمر في العبادة ومتّبعش خطوات الشيطان،\nفي وسط الإحباط واليأس إللي كان فيه جاءه الشيطان في صورة بشر وقال له : \nأنا إللي عملت معاك كل ده، وأنا دلوقتي أقدر أنجيك من إللي انت فيه\nفقال له برصيصا : فعلا تقدر تخلصني\nفقال له الشيطان : سأنجيك بشرط إنك تسجد لي سجدة واحدة وكل إللي انت فيه ده ينتهي وترجع لحياتك \nرفض برصيصا في الأول إنه يسجد له، لكن مع إغواء الشيطان ووعوده له والموقف الصعب إللي كان فيه سجد للشيطان سجدة فقتلوه الناس ومات على الشرك\n\"كَمَثَلِ الشَّيْطَانِ إِذْ قَالَ لِلْإِنسَانِ اكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّي بَرِيءٌ مِّنكَ إِنِّي أَخَافُ اللَّهَ رَبَّ الْعَالَمِينَ ۩\nفَكَانَ عَاقِبَتَهُمَا أَنَّهُمَا فِي النَّارِ خَالِدَيْنِ فِيهَا ۚ وَذَٰلِكَ جَزَاءُ الظَّالِمِينَ\"\n☆لو كان برصيصا صادق الإيمان بالله وعنده علم بالله مكنش وقع في الشرك في آخر لحظة ومكنش طلب من الشيطان إنه ينجيه، \nبقاله أكثر من سبعين سنة بيعبد الله غلط... في قلبه شبهة أو مرض أو جهل بالله أو...أو... عشان كده كانت النتيجة هي حبوط عمله ودخوله النار،\nبعكس جُريج العابد فاكرينه،\nجريج تعرض للفتنة ولأنه كان عالم عابد استطاع إنه يتجنب الفتنة وميقعش فيها،\nوكان عنده ثقة في الله إنه هينجيه لما صلى ودعا الله وبعدين سأل الطفل الرضيع وقال من أبوك فأنطق الله الطفل الرضيع لجريج\nالعبادة لوحدها مش كفاية للنجاة من الفتن لازم العلم، لازم المسلم يعرف مين هو ربنا إللي بيعبده وإيه هي أسماءه وصفاته، \nمن غير العلم الإنسان هيضل ويقع في الفتن،\nيا جماعة ربنا لا يُضل من كان صادق من قلبه في عبادته سبحانه، عشان بس الناس إللي دايما تقول محدش بعيد عن الفتنة ويبقى قصدهم إن ممكن ربنا في لحظة يُضل إنسان عابد طائع مخلص في ظاهره وباطنه كده وخلاص،\nمش فاهمين إن ربنا هو الصادق الوفي ، وإنه يعامل الناس بكسبهم ، ويجازيهم بأعمالهم ولا يُضيع عمل محسن أبدا ، ولا يضيع على العبد مثقال ذرة \nخدوها قاعدة لو شوفتم إنسان ربنا أضله بعد هدى فهو بسبب:\n ◇إما ذنوب خلوات تجرأ فيها العبد على الله وشايف إن ده حاجة عادية وغير نادم ومش بيحاول يصلح من نفسه.\n◇أو إنه كان بيعمل الأعمال الصالحة عشان الناس، وفي قلبه مرض، سواء عُجب أو رياء أو أي مرض من أمراض القلوب وهو مش بيصلحه\nنسأل الله أن يثبتنا ويغفر لنا وألا يزيغ قلوبنا بعد إذ هدانا وأن يبعدنا عن اتباع خطوات الشيطان \nإن شاء الله المرة الجاية هنكمل الكلام عن السرايا وبعض آيات سورة النور\n☆"}, {"n": 133, "l": "الجزء 107 | أحداث السنه السادسه من الهجرة | وليضربن بخمرهن علي جيوبهن | آثار الغزوات والسرايات بعد الأحزاب", "u": "", "t": "غض البصر، واحكام الحجاب وتكملة سورة النور\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وسبعة\n#أحداث_السنة_السادسة_من_الهجرة\n#وليضربن_بخمرهن_على_جيوبهن\n#آثار_الغزوات_والسرايا_بعد_الأحزاب\nاتكلمنا المرة إللي فاتت عن نزول سورة النور وشوفنا بعض النقط إللي بتتكلم عنها السورة ومن النقط دي كان الأمر بغض البصر والنهي عن إبداء الزينة لغير المحارم،\nخلونا نشوف الآية :\n\"وَقُل لِّلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ\"\nوالمقصود إن المرأة تصرف نظرها عن مَن تشتهي رؤيتَه من الرجال الأجانب، وتُنقِص من النظر إلى الشهوات؛ للحذر من الفتنة في الدين،\n فالكلام معناه إن غض البصر أنواع:\n◇الأول: \nهو عدم النظر إلى الجنس الآخر.\n◇ الثاني : \nغض البصر عن عورات النساء فيما بينهن أو عورات الرجال فيما بينهم، يعني مش عشان النساء أو الرجال زي بعض بقى يبقى مفيش بينهم عورات،\nلأ...المرأة يجب عليها غض البصر عن عورة المرأة إللي زيها و كذلك الرجل يجب عليه غض بصره عن عورة الرجل إللي زيه.\n◇ الثالث: \nغض البصر عن رزق الناس و أملاكهم؛ لأن ده سبب في فتنة الإنسان، لما مثلا امرأة تشوف عند صاحبتها ولّا قريبتها ذهب ويعجبها وتشوف الإعلانات عن متاع الدنيا باختلاف أنواعه وكذلك الرجل لما يشوف متاع من الدنيا لا يملكه، إيه إللي هيحصل\nالطبيعي إن النفس هتشتهي الحاجة دي، طيب مفيش أموال، يبقى هيعرّض نفسه إنه يشتغل بزيادة ويضيع حقوق ربنا عليه،\nوممكن مع زيادة إطلاق النظر وشدة الرغبة في متاع الدنيا الإنسان يقع في المحرم زي السرقة أو إنه يحصل على المال بطريقة غير مشروعة،\nوهتلاقوا إن كل مصائبنا كبشر نتيجة اهتمامنا بأملاك وأرزاق بعضنا البعض، وحتى الحروب إللي عرفتها البشرية كانت بسبب الجشع و النظر و الطمع فى ما عند الآخرين\nفأقوى الحواس ارتباطا بالقلب هي حاسة البصر، لأن الإنسان إذا شاف حاجة عجبته وخلاص دخلت قلبه بقى عايزها،\nعشان كده رسول الله ﷺ قال :\n\" انظروا إلى من هو أسفل منكم في الدنيا وفوقكم في الدين فذلك أَجْدرُ ألا تَزْدَروا نعمة الله عليكم\"\nوإطلاق البصر سواء في المحرمات أو الشهوات بيخلي في القلب حسرة وحُرقة، \nلأن الواحد بيشوف حاجة نفسه فيها ومش قادر يحصل عليها وده من أعظم العذاب للإنسان\nوطبعا مش هتكلم عن العشق المحرم المنتشر بين الشباب دلوقتي وإنه كان بدايته النظر\nفي حين إن إللي بيغض بصره ربنا بينور له بصيرته ويشوف بعين قلبه وفِراسته إللي غيره ميشفهوش، وبالتالي يتجنب الوقوع في مشاكل كثيرة،\nواحنا اتكلمنا قبل كده عن البصيرة في الجزء السابع والثمانون لو حبيتم ترجعوا له وتفتكروا معناها وإزاي الإنسان يكون عنده بصيرة \nوغض البصر بأنواعه الثلاثة له فوائد كثيرة ،\nمن أهمها من وجهة نظري \nالأُنس بالله وإن الإنسان يبقى عنده بصيرة\n☆وهتلاقوا رابط في التعليقات فيه فوائد غض البصر ممكن تقرأوا الفوائد دي عشان تساعدكم على غض البصر\nوإللي هيحفظ بصره هيقدر يحفظ فرجه في الغالب، عشان كده ربنا ربط بين الإثنين، أمر بحفظ البصر ووراه على طول أمر بحفظ الفرج سواء عن الزنا والسّحاق أو غيره،\nولأن النظر هو سبب كل المشاكل والفتن ربنا أمر المرأة إنها لا تُظهر زينتها وهي خارجة من بيتها عشان متلفتش النظر إليها؛ لأن الطبيعي إن العين هتلقط أي حاجة شكلها حلو ومُزينة\nواحنا اتكلمنا قبل كده في جزء 《لماذا النساء》 ووضحنا أد إيه المرأة فتنة شديدة على الرجل،\nفربنا أمر النساء إنهن لا يُظهرن زينتهن واستثنى إللي يظهر منها غصب عنها، \nيعني ربنا قال إلا ما ظهر منها مقلش إلا ما أظهرن منها، يعني المرأة متتعمدش إنها تبين منها شيء، \n\"وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا \"\nوطبعا المرأة مُباح لها إنها تُظهر زينتها أو مواضع زينتها أمام المحارم، \n\"وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَانُهُنَّ أَوِ التَّابِعِينَ غَيْرِ أُولِي الْإِرْبَةِ مِنَ الرِّجَالِ أَوِ الطِّفْلِ الَّذِينَ لَمْ يَظْهَرُوا عَلَىٰ عَوْرَاتِ النِّسَاءِ\"\nوزيادة في الستر ربنا أمر النساء أنهن يغطين فتحة الصدر إللي كانت في الجلابيب إللي كانوا لابسينها، لأن النساء كانت بتسيب شق كده من عند الرقبة لحد أسفل الصدر عشان يقدروا يرضعوا أولادهن، فكانت منطقة الصدر دي بتظهر غصب عنها،\n\"وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ\"\nفلما نزلت الآية دي نساء المهاجرات الأُوَل شققن أُزُرَهن فاختمرن بها زي ما قالت السيدة عائشة رضي الله عنها ،\nيعني كل واحدة جابت الإزار بتاعها وشقته ولبسته من على رأسها وغطت بيه فتحة الجيب، والإزار يعني ما يُلبس على الجزء الأسفل من الجسم،\nوخدوا بالكم إن اتفاق الصحابيات على تطبيق الآية بالمنظر ده حُجة؛ لأن رسول الله ﷺ شافهم وهم متغطيين كده،\nولو كانوا فهموا غلط أو تطبيقهم للآية كان غلط كان رسول الله ﷺ اعترض وقال لهم لأ انتم فهمتوا غلط والصح كذا وكذا\nفالآية دي مُكملة وشارحة لآية سورة الأحزاب \n\" يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ\"\nفالنساء زوّدوا الستر مش قلّلوه، أو إنهم مكنوش مغطيين وجوههم فغطوها،\nفالآية بتأكد على تغطية المرأة لجميع جسدها بما فيه الوجه،\n\"وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ\"\nواحنا قلنا إن زوجات رسول الله ﷺ وزوجات المؤمنين كانوا مغطيين وجوههن من ساعة نزول آية سورة الأحزاب واتكلمنا بالتفصيل عن تفسير الآية في جزء الحجاب في الإسلام،\n☆بكرر وبعيد \nأنا بشرح السيرة يعني بشرح أفعال رسول الله ﷺ والصحابة كانت إيه ورد فعل رسول الله ﷺ على أفعالهم،\nموضوع بقى اختلاف العلماء وقول ابن العباس إن إللي ظهر المقصود به في الآية الوجه والكفين، \n\"إِلَّا مَا ظَهَرَ مِنْهَا\"\nكل ده مخالف للتفسير الصحيح للآية وفعل الصحابيات زي ما شوفنا،\nوبالمناسبة كل الكلام المنسوب لعبد الله بن عباس عن الوجه والكفين فهو كله روايات ضعيفة، ويقابلها روايات صحيحة بتقول عكس الكلام، \nوحتى لو سلّمنا باختلاف العلماء فالقول الراجح من الإختلاف بتاعهم إن تغطية الوجه والكفين فرض على كل امرأة حرة،\nفيا ترى بقى إللي عايز يتبع رسول الله ﷺ وصحابته عشان يُحشر معاهم يوم القيامة هياخد بالصحيح ولّا بالضعيف\nوبالنسبة لتفسير إلا ما ظهر منها فدي معناها ثياب المرأة الظاهرة إللي مفيهاش زينة،\n《الكلام عن تفسير الآية باختصار من كتاب عودة الحجاب الجزء الثالث الباب الخامس للشيخ محمد إسماعيل المقدم 》\nرابط الكتاب في التعليقات\n والكتاب ده مهم جدا يا جماعة إللي يقدر يقرأه هيستفيد منه جدا\nنرجع لأحداث الجهاد والسرايا ،قلنا إن رسول الله ﷺ مهما كان مشغول بالأحداث الداخلية في المدينة فهو كان متابع للأخبار في شبه الجزيرة العربية عن طريق العيون إللي كان زارعها هنا وهناك ومهمتها إنها تعرف أخبار وتحركات القبائل زي فريق استخبارات كده،\nوصل الخبر لرسول الله ﷺ إن امرأة من بني فَزَارة اسمها أم قِرْفة في منطقة وادي القرى جهزت فرقة من ثلاثين أو أربعين فارس من أولادها وأحفادها مهمتها اغتيال رسول الله ﷺ، وأم قرفة كانت زعيمة في بني فزارة لها شأنها ومكانتها وقومها بيعظموها،\nفجهز رسول الله ﷺ سرية بقيادة زيد بن حارثة رضي الله عنه، ومهمة السرية دي القضاء على الثلاثين فارس،\nفخرجت السرية في شهر رمضان وتوجهت لمنطقة وادي القرى،\nهجمت السرية على الفرسان وقتلتهم جميعا، وقتلوا أم قرفة لأنها كانت تقاتل وتحرض على قتل رسول الله ﷺ،\nلكن الأصل إن النساء لا تُقتل، فلو قاتلت وحرضت على قتال رسول الله ﷺ والمسلمين تُعامل معاملة المحارب وتُقتل في المعركة زيها زي الرجل،\n☆وفي هنا شبهة أعداء الإسلام بيفتروها على رسول الله ﷺ،  بيقولوا إن رسول الله ﷺ لما قتل أم قرفة ربط كل رجل من رجلها في حصانين وخلى الحصانين يجروا عكس اتجاه بعض فانفسخت المرأة وقُتلت بالطريقة دي\nطبعا الكلام غير صحيح، لأن زيد بن حارثة هو إللي قتلها أصلا في بلدها مع الثلاثين فارس وأخذ درعها وأرسله لرسول الله ﷺ في المدينة،\nيعني رسول الله ﷺ مشفهاش من الأساس\nوكمان رسول الله ﷺ كان دائما ينهى الصحابة عن التمثيل بالقتل وهو القائل : \n\"إن الله كتب الإحسان على كل شيء، فإذا قتلتم فأحسنوا القتلة، وإذا ذبحتم فأحسنوا الذبح وليحد أحدكم شفرته، وليُرِح ذَبِيحته\"\nفإذا كان إحسان القتلة مأمور به عند ذبح البهيمة، فكيف بالإنسان \nفكل الروايات إللي بتتكلم عن طريقة القتل دي روايات ضعيفة، وروايات السّيَر وقصص التاريخ لا يُثبَت بها حكم وخصوصا لما تناقض الأحكام الشرعية إللي جاءت في الأحاديث الصحيحة\nفي نفس شهر رمضان حصل جَدب شديد ومفيش مطر بينزل، وجزيرة العرب معتمدة في الأساس على الأمطار،\nفاشتكى الناس لرسول الله ﷺ،\nفقام رسول الله ﷺ وجمع الناس وصلى ركعتين ودعا الله عز وجل فأنزل الله المطر عليهم كالسيل،\n☆ودي اسمها صلاة الاستسقاء، وصلاة الاستسقاء زي صلاة العيد كده، الركعة الأولى سبع تكبيرات وبعدين الفاتحة وما تيسر من القرآن والركعة الثانية خمس تكبيرات والفاتحة وما تيسر من القرآن،\nوبعد الصلاة الإمام يخطب في الناس ويعظهم ويدعو الله عز وجل والناس تُأَمّن على الدعاء.\nفي شهر شوال رسول الله ﷺ أخرج سريتين:\n◇السرية الأولى كانت لقتل مجموعة من المشركين من قبائل عَكَل وعُرَيْنَة، والمجموعة دي كان عددهم ثمانية جاءوا للمدينة وأسلموا عند رسول الله ﷺ وبعدين لقوا إن المدينة مش مناسباهم ومش عاجبهم يقعدوا فيها، وكانوا مرضى وفي رواية إنهم اشتكوا وجع في بطونهم،\nفاشتكوا لرسول الله ﷺ من مرضهم، فأرسلهم رسول الله ﷺ مع راعيه ومعاه إبل الصدقة لطرف المدينة ناحية قُباء،\nوقال لهم يقعدوا هناك ويشربوا من لبن الإبل دي ومن بولها،\nفلما خفّوا من المرض وصحتهم رجعتلهم قطعوا يد راعي رسول الله ﷺ ورجليه وسخنوا مسامير ووضوعها في عين الراعي وتركوا كده لحد ما مات\nوأخذوا الإبل ومشيوا بيها...سرقوها يعني،\nوصل الخبر لرسول الله ﷺ فجهز بسرعة سرية من عشرين فارس بقيادة كِرْز بن جابر الفهري وأرسلهم وراء العُرَنِيّين الثمانية المشركين دول،\n☆وكرز بن جابر ده لو تفتكروا لما حكينا في الجزء الخامس والخمسين كان هو إللي هجم على أطراف المدينة وحصلت بسببه غزوة سَفْوان أو غزوة بدر الأولى، وأسلم بعدين\nالمهم الأحداث دي كانت في أول النهار، على آخر اليوم كان العشرين فارس لحقوا الثمانية من المشركين وقبضوا عليهم وكتفوهم واسترجعوا الإبل ورجعوا لرسول الله ﷺ،\nوأنزل الله تعالى:\n\"إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا أَن يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَافٍ أَوْ يُنفَوْا مِنَ الْأَرْضِ ۚ \nذَٰلِكَ لَهُمْ خِزْيٌ فِي الدُّنْيَا ۖ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ\"\nلما وصلوا لرسول الله ﷺ أمر بهم رسول الله ﷺ فقطعت أيديهم وأرجلهم ووضعت المسامير المُسخنة في أعينهم زي ما عملوا في الراعي بالضبط، وتركهم في الصحراء ليموتوا\nوده كان أشد عذاب عذب به رسول الله ﷺ أحد، \nوده بسبب جرائمهم إللي وراء بعض: رِدة عن الإسلام وتعذيب وقتل وسرقة وكل ده كان مقابل الإحسان إللي أحسن به رسول الله ﷺ إليهم.\n◇السرية الثانية في شهر شوال كانت بقيادة عبد الله بن رَوَاحة، ومهمة السرية دي كانت اغتيال اليُسير بن رزام،\nواليُسير بن رزام ده كان زعيم اليهود في خيبر بعد مقتل أبو رافع سلاّم بن أبي الحقيق،\nمش يتعظ بقى ويحافظ على حياته بعد مقتل حيي بن أخطب وأبو رافع، لأ...ده قعد يجمع اليهود في منطقة خيبر ومنطقة وادي القرى ومنطقة فَدَك،\nومش بس كده ده بدأ يجمع غطفان مرة ثانية عشان يحارب المسلمين ويعيد الأحزاب مرة ثانية\nيعني عايز يقوم بنفس الدور إللي قام به حُيَي بن أخطب وأبو رافع اليهودي،\nوعشان مأساة حصار المسلمين في المدينة متتكررش رسول الله ﷺ كان حريص إنه يتخلص منه قبل ما يحقق هدفه في تجميع المشركين، وبكده هيحمي المسلمين من أزمة كبيرة جدا ممكن تحصل لهم،\nوكان عدد السرية دي ثلاثين فارس  واستطاعوا إنهم يقتلوا اليُسير بن رزام، وبكده أمِن المسلمون من شر يهود خيبر،\nولكن بصفة مؤقتة\nاحنا أه خلصنا من زعيمهم بس اليهود نفسهم موجودين وهي مسألة وقت لحد ما يجمعوا نفسهم تاني ويحاولوا يهجموا على المسلمين،\nعشان كده لازم حل نهائي لمشكلة اليهود في خيبر عشان نخلص من شرهم زي ما خلصنا من بني قينقاع وبني النضير وبني قريظة\nلكن المشكلة إن رسول الله ﷺ مش هيقدر يدخل دلوقتي في حرب مع يهود خيبر، لأن قريش ممكن تستغل فرصة خروج رسول الله ﷺ من المدينة ويقوموا جايين هاجمين على المدينة أو هيجموا على جيش رسول الله ﷺ من خلفه،\nويبقى رسول الله ﷺ محصور بين جيش اليهود من الأمام وجيش المشركين من خلفه \nوبكده المسلمين هيتعرضوا للإبادة زي إللي كان هيحصل بالضبط في غزوة الأحزاب، وخصوصا إن حصون خيبر قوية محتاجة حصار ومقاتلينها أقوياء جدا، فالموضوع محتاج له وقت،\nعشان كده رسول الله ﷺ اكتفى بس إنه يقتل رأس الفتنة اليُسير بن رزام لحد ما يشوف هيعمل إيه مع قريش\nكده يبقى عدى على غزوة الأحزاب سنة كاملة، من شوال سنة خمسة هجريا إلى شوال سنة ستة هجريا، حصل خلال السنة دي حوالي عشرين غزوة وسرية زي ما شوفنا،\nوالغزوات والسرايا دي كان لها أثار كثيرة منها:\n♡ تحسن الوضع الأمني للمسلمين في الجزيرة العربية، مبقاش في حد بيعتدي على المسلمين زي ما كان بيحصل في الأول.\n♡ تحسن المستوى العسكري والأداء القتالي للمسلمين جدا، لأن الغزوات والسرايا دي كانت زي دورات عسكرية عملية،\nواحنا عارفين إن التجربة العملية مختلفة تماما عن الكلام النظري\n♡ تحسّن الوضع الاقتصادي للدولة الإسلامية، لأن الإستقرار بيشجع على التجارة، وكمان بسبب الغنائم إللي أخذها المسلمين في الغزوات والسرايا.\n♡بقى في علاقات دبلوماسية بين المسلمين وقبائل العرب القوية، زي بني المصطلق إللي رسول الله ﷺ تزوج من بنت ملكهم جويرية،\nوزي بني كلب في دومة الجندل إللي عبد الرحمن بن عوف تزوج من بنت ملكهم، ومننساش موقف ثمامة بن أثال وإسلامه بسبب أسره في سرية محمد بن مسلمة.\n♡قريش بدأت قوتها تضعف لأنها خسرت التحالف مع القبائل إللي رسول الله ﷺ كسبها في صفه، وبكده بدأت قريش تفقد سيادتها على العرب \nده غير بقى ضعف قوة اليهود بسبب خسارة زعماءهم الواحد وراء التاني، يعني إللي يشوف الحال يلاقي إن دولة الإسلام بتفرض سيطرتها شوية شوية ومفيش حد قادر يوقف السيطرة دي،\nوخدوا بالكم إن لو كان مجتمع الصحابة مش متربي تربية إيمانية مكنش قدر يفرض سيطرته دي\nالصحابة لما كان يأتيهم الأمر من الله أو من رسوله كانوا بينفذوه فورا من غير أي اعتراض، واحنا شوفنا رد فعل الصحابة لما نزل تحريم الخمر مثلا وشوفنا النساء عملت إيه لما نزلت آية الحجاب،\nومش كده وبس ده في مواقف للصحابة الواحد يستغرب منها جدا،\nيعني مرة رسول الله ﷺ كان في المسجد بيخطب فقال للصحابة إللي كانوا في المسجد اجلسوا، فسمعه عبد الله بن رواحة وهو خارج المسجد فراح قاعد في الأرض لحد ما رسول الله ﷺ خلص الخطبة بتاعته،\nرسول الله ﷺ لما عرف إللي عمله عبد الله بن رواحة دعا له وقال :\nزادك الله حرصا على طواعية الله تعالى وطواعية رسوله\nمع إن عبد الله بن رواحة كان ممكن يقول لنفسه ده رسول الله بيقول للناس إللي في المسجد،\nأو على الأقل كان يدخل المسجد الأول وبعدين يقعد فيه بدل ما يقعد في الشارع كده لوحده، مفكرش في شكله قصاد الناس ولا إن الناس ممكن تتريق عليه ولا تنتقده،\nهو سمع كلمة من رسول الله ﷺ فنفذها في نفس اللحظة،\nموقف تاني، \nرسول الله ﷺ كان بيصلي وهو لابس نعله، حذاءه يعني فخلعهما وهو بيصلي راح الصحابة كلهم خالعين نِعالهم هم كمان في الصلاة\nفبعد الصلاة رسول الله ﷺ سألهم إنتم ليه خلعتم نعالكم؟!\nقالوا له :\nشوفناك خلعت نعالك فخلعنا\nفقال لهم إن جبريل عليه السلام جاءه وقال له إن نعله فيه قذرا، فعشان كده خلعهما،\nشوفتم اتباع الصحابة لرسول الله ﷺ عامل إزاي، مع إنهم لو استنوا لحد ما رسول الله ﷺ يخلص صلاة وسألوه مكنش هيبقى في مشكلة،\nتعتقدوا أمة زي دي يقدر حد يغلبها، وربنا وعدهم بالاستخلاف في الأرض ماداموا طائعين:\n\"وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِي ارْتَضَىٰ لَهُمْ \"\nفانتشار سيطرة المسلمين خارج المدينة كانت نتيجة لطاعتهم لله ولرسوله وأخذهم بأسباب النصر،\nوأي حد عايز يحقق النتائج إللي حققوها يبقى لازم يلتزم بنفس منهجهم وهو الطاعة العمياء لله ولرسوله\n\"وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ ذَلِكُمْ وَصَّاكُمْ بِهِ\"\nفي نفس الشهر شهر شوال رسول الله ﷺ شاف رؤيا، وبسبب الرؤيا دي  هتحصل أحداث كبيرة جدا هيكون لها الأثر مش بس على شبه الجزيرة العربية لكن كمان على العالم كله\nإيه هي الرؤيا دي وإيه الأحداث إللي حصلت بعد كده ده إللي هنعرفه المرة الجاية إن شاء الله \n♡إللي عايز يعرف شرح سورة النور هيلاقي في التعليقات رابط لحلقات تفسير السورة للدكتور ناصر العُمر،\nجميلة جدا والحلقة نص ساعة بس فمش هتزهقوا\n☆"}, {"n": 134, "l": "الجزء 108 | احداث السنه السادسه من الهجرة | الطريق إلى الحديبيه", "u": "", "t": "الي ميصليش العصر ف عمله اليوم كله محبط \n واي الرؤية الي جت للنبي صلي الله عليه وسلم \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثمانية\n#أحداث_السنة_السادسة_من_الهجرة\n#الطريق_إلى_الحُدَيْبِيَة\nوقفنا المرة إللي فاتت عند الرؤيا إللي شافها رسول الله ﷺ،\nوقلنا إن بسبب الرؤيا دي هتحصل أحداث كبيرة جدا هيكون لها الأثر مش بس على شبه الجزيرة العربية لكن كمان على العالم كله\nإيه بقى الرؤيا دي\nرأى رسول الله ﷺ إنه أخذ أصحابه وذهبوا لمكة وطافوا بالبيت الحرام،\nورؤيا الأنبياء وحي، يعني كده ربنا أمر رسول الله ﷺ إنه يأخذ الصحابة ويروحوا يعملوا عمرة،\nلكن إزاي رسول الله ﷺ والصحابة معاه هيروحوا يعملوا عمرة وفي حرب قائمة بينهم وبين قريش\nلأ وقريش من سنة واحدة بس كانوا جايبين عشرة آلاف مقاتل وجايين يحاربوا المسلمين، \nده كده هيبقوا بيسلموا لهم نفسهم وخصوصا إن مفيش بينهم أي معاهدات\nرسول الله ﷺ أخبر الصحابة بالرؤيا وقال لهم يتجهزوا للعمرة، الصحابة بدأوا يتجهزوا للعمرة من غير ما يسألوا ولا يعترضوا ولا أي حاجة خالص\nمع إن السفر لمكة في الوقت ده فيه خطر عليهم، ومع ذلك رضيوا وقبلوا وبدأوا يتجهزوا للخروج مع رسول الله ﷺ،\nقريش كان عندها قانون مُتعارف عليه بين العرب وهو إن إللي يذهب إلى مكة لأداء العمرة فهو آمن مهما كان الخلاف إللي بينه وبين قريش\nوالقانون ده كان في مصلحة رسول الله ﷺ والصحابة، كده قريش مش هتقدر تعمل لهم حاجة\nفرسول الله ﷺ استغل القانون ده لمصلحته وبكده قريش مش هتقدر تتعرض للمسلمين بأذى،\nلكن هل قريش بقى هتلتزم بالقانون ده ولا هييجوا لحد المسلمين وميطبقوش القانون\nده إللي هنعرفه كمان شوية، \nتجهز ألف وأربعمائة صحابي للخروج للعمرة مع رسول الله ﷺ، \nوطبعا كل المنافقين مخرجوش مع رسول الله ﷺ لأنهم كانوا شايفين إن المشوار ده مُهلك، ما عدا رجل واحد منهم،\nفهم إزاي يروحوا للأعداء في عُقر دارهم ومش معاهم غير سلاح المسافر فقط وهو السيف مش سلاح المُحارب، يعني دي عملية انتحارية من وجهة نظرهم،\nفكل إللي خرج مع رسول الله ﷺ للعمرة كانوا من المؤمنين الصادقين ما عدا منافق واحد وهو الجَدّ بن قَيْس،\nوخرج مع رسول الله ﷺ من زوجاته في السفر ده السيدة أم سلمة رضي الله عنها،\nخرج رسول الله ﷺ من المدينة مع الصحابة في اتجاه مكة وكان خروجهم في شهر ذي القعدة من السنة السادسة للهجرة، وأخذ معاه مجموعة كبيرة من الإبل وقلّدها يعني وضع في رقبتها جلدة عشان يتعرف إن الإبل دي من الهَدْي إللي هيُذبح  في مكة، \nووصل إلى ذي الحُلَيفة أو ما يسمى الآن بأبار علي، وهو المكان إللي بيُحرِم منه القادم من المدينة إلى مكة،\nيبقى رسول الله ﷺ لبس ملابس الإحرام وبدأ بالتلبية والصحابة معاه،\nوبقى واضح جدا إن رسول الله ﷺ رايح للعمرة، وهو يعلم ﷺ إن في عيون لقريش على الطريق والعيون دي هتنقل الخبر لقريش،\nورسول الله ﷺ مش عايز قتال مع قريش هو شاف في الرؤيا إنه بيعتمر فقط، مكنش في أي قتال\nفكده قريش على حسب قانونها ملهاش أي حجة إنها ترد المسلمين أو تمنعهم من أداء العمرة\nرسول الله ﷺ كان عايز يعرف رد فعل قريش على خروجه للعمرة فأرسل واحد من الصحابة اسمه بِشر بن سفيان الخزاعي يستطلع الخبر،\nفلقى إن قريش جمعت جيش وجمعت الأحابيش عشان يمنعوا رسول الله ﷺ من الدخول لمكة،\nوالأحابيش دول مجموعة من القبائل تحالفت مع قريش عند جبل اسمه حبشي وعاملين مع بعض اتفاقية دفاع مشترك للدفاع عن مكة،\nرجع بِشر لرسول الله ﷺ وأخبره الخبر،\nفقال رسول الله ﷺ:\nيا ويح قريش! قد أكلتهم الحرب، \nيعني الناس دي مشتاقة للحرب بشكل غير مفهوم، يعني احنا اتحاربنا مرة واتنين وثلاثة خلاص بقى، \nوأنا موضح إني جاي أعمل عمرة ومش معايا غير سلاح المسافر فليه التصميم على القتال ده؟\nولو انهم فكروا بعقل شوية مش هيبقى في مشكلة لو خلوا بيني وبين العرب أقابلهم وأدعوهم، فلو قتلوني خلاص هو ده إللي هم عايزينه،\nولو ربنا أظهرني عليهم يدخلوا في الإسلام من غير ما حد يموت منهم، أو على الأقل هيقاتلوني وهم فيهم قوة لأنهم كانوا مرتاحين وأنا إللي تعبان في الحروب\nوصل رسول الله ﷺ في طريقه لمنطقة اسمها كُرَاع الغَميم،\nوهي على بعد حوالي ستين كيلو من مكة،\nوهناك كان مستنيه خالد بن الوليد ومعاه فرقة مقاتلة مكونة من مائتين فارس واقفين بكامل سلاحهم عشان يَصُدوا رسول الله ﷺ عن العمرة،\nمع إن على حسب القانون بتاعهم رسول الله ﷺ له الحق الكامل إنه يدخل مكة مُعزز مكرم وكمان في حماية أهل مكة وأهل مكة مُلزمين إنهم يراعوا حقوق المسلمين ويخدموهم زي ما بيخدموا أي حد تاني بييجي للعمرة\nلكن زي مانتم عارفين القوانين إللي فيها مصلحة بتيجي عند المسلمين وتقف\nالعالم ينادي بالحرية للجميع وإعطاء الناس حقوقهم، لكن ييجوا عند المسلمين ويقولوا لأ ويمعنوهم من ممارسة حقوقهم\nالمهم يعني قريش ضربت بقوانينها عرض الحائط وبدأت تتعامل بنوع من الغدر ومخالفة القوانين والعهود التي بينها وبين العرب، وكل ده عشان تمنع رسول الله ﷺ من أداء العمرة،\nدلوقتي رسول الله ﷺ في موقف صعب، مستنيه جيش مُجهز ومستعد للحرب وهو مش معاه غير ألف وأربعمائة مش معاهم غير سلاح المسافر إللي هو السيف فقط زي ماقلنا من شوية، \nفجمع رسول الله ﷺ الصحابة وبدأ يستشيرهم يعملوا إيه في الموقف ده\nرسول الله ﷺ كان دائما يستشير أصحابه في كل المواقف إلا لو في وحي فيبقى مفيش استشارة، في تنفيذ أوامر فقط زي خروجهم للعمرة كده،\nفرسول الله ﷺ لم يستشِر الصحابة في الخروج للعمرة ولكنه أمرهم بالخروج،\nهنا مفيش وحي يقول لرسول الله ﷺ يعمل إيه بالضبط،\nهل يُقاتل الجيش إللي اتجمع ده ولّا يرجع للمدينة ولّا يدخل مكة غصب، \nولّا يروح يهجم على قبائل الأحابيش إللي دلوقتي مفيهاش مقاتلين يدافعوا عنهم وبكده هتقوى شوكة المسلمين أكثر؟\nكل دي أفكار مطروحة أمام الصحابة،\nأبو بكر الصديق رضي الله عنه قال لرسول الله ﷺ :\nاحنا جئنا للعمرة ولم نأتِ لقتال أحد، ولكن إللي هيقف قصادنا ويمنعنا من العمرة هنقاتله\nيعني رأي أبي بكر إنهم يتقدموا ويكملوا الطريق لحد ما يوصلوا لبيت الله ولو جيش مكة اعترضهم بالقوة، المسلمين هيقاتلوهم لكن المسلمين نفسهم مش هيسعوا للقتال،\nفالصحابة عجبهم رأي أبي بكر رضي الله عنه وكملوا الطريق،\nلكن قريش مصرة إنها تمنع رسول الله ﷺ من الدخول لمكة، لما اقترب رسول الله ﷺ من فرقة خالد المقاتلة كان جاء وقت صلاة الظهر،\nوقف الصحابة يصلون خلف رسول الله ﷺ صلاة الظهر قصرا يعني ركعتين فقط لأنهم كانوا مسافرين، \nركعوا وسجدوا وخالد بن الوليد شايفهم من بعيد وبيراقبهم\nودي كانت أول مرة خالد بن الوليد يشوف المسلمين وهم بيصلوا بالشكل ده، فلاحظ إن المسلمين وهم ساجدين مش بيشوفوا إللي قصادهم، فلقى إن دي فرصة مناسبة جدا للهجوم على المسلمين\nوسأل المشركين إللي معاه هل في صلاة تانية للمسلمين زي الصلاة دي؟\nفقال له بعض المشركين إللي يعرفوا أحوال المسلمين:\nعندهم صلاة ثانية اسمها صلاة العصر وهي أحب إليهم من أنفسهم وأبنائهم\nفقرر خالد بن الوليد في نفسه من غير ما يقول لأي أحد إنه هيهجم على المسلمين وهم ساجدين في صلاة العصر.\n☆واخدين بالكم إن المشركين قالوا عن صلاة العصر إنها أحب للمسلمين من أنفسهم وأبنائهم، يا ترى إيه إللي المشركين شافوه من الصحابة عشان يوصلوهم إنهم يقولوا الكلام ده عنهم\nإزاي وصل للمشركين إن صلاة العصر أحب للصحابة من أنفسهم وأبنائهم\nهو أكيد لما نعرف حديث رسول الله ﷺ:\n\"من ترك صلاة العصر فقد حبط عمله\"\nهنفهم أد إيه الصحابة كانوا حريصين على صلاة العصر بالذات،\nوالعلماء قالوا في شرح الحديث إن إللي يسيب صلاة العصر بالكلية عمله كله يحبط، \nأما إللي ميصليش صلاة العصر في يوم مع القدرة على الصلاة فعمل اليوم ده كله يَحبط\nده غير تخصيص الأمر بالمحافظة على صلاة العصر بالذات في قوله تعالى:\n\"حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَىٰ \"\nوغيرها من الأحاديث،\nوالصحابة بصفة عامة مكنوش بيضيعوا الصلاة ولا بيأخروها عن وقتها إلا في الظروف الضيقة جدا زي ما شفنا كده إللي حصل في غزوة الأحزاب،\nغير كده كانوا حريصين جدا إنهم يؤدوا الصلاة في وقتها، حتى وقت القتال والجهاد ولو اشتد القتال كانوا بيصلوا وهم على الخيول بإيماء الرأس،\nلما جاء وقت صلاة العصر اصطف المسلمون للصلاة، وهنا هتبقى فرصة خالد بن الوليد للهجوم على المسلمين، لكنه شاف إن الصلاة اتغيرت\nلقى إن نص الصحابة واقفين للحراسة والنص الثاني بيصلي مع رسول الله ﷺ،\nوالصلاة دي اسمها صلاة الخوف نزل بها الوحي بين صلاة الظهر وصلاة العصر،\nوربنا شرعها عشان حماية الجيش المسلم أثناء الحروب،\nوصلاة الخوف دي من الأدلة إللي بيستدل بيها العلماء على وجوب صلاة الجماعة على الرجال،\nلأن لو صلاة الجماعة مش فرض على الرجال كان ربنا أسقطها وقت الحرب على الأقل\nبعد ما رسول الله ﷺ صلى الركعتين مسلمش، فضل قاعد والصحابة إللي كانوا بيصلوا معاه سلموا وقاموا أخذوا الأسلحة بتاعتهم وبدأوا يقوموا بدور الحراسة،\nوالنص إللي كان واقف بيحرس جاء ليصلي خلف رسول الله ﷺ،\nوصلى بهم رسول الله ﷺ ركعتين تانيين وسلم وسلموا معاه،\nخالد بن الوليد لما شاف الموقف إللي حصل ده قال:\nإن القوم مَمْنوعون\nيعني الناس دي عندهم حماية إلاهية، ده خارج حدود البشر، \nهو مقلش لأي حد إطلاقا على الخطة بتاعته والصلاة دي أول مرة يصلوها بالطريقة دي، فاشمعنى المرة دي يعني إللي صلوا الصلاة دي\nفكان واضح جدا لخالد بن الوليد إن في إله بيدبر للمسلمين أمورهم ويعلم ما نفسه.\n☆ولعل الموقف ده كان هو السبب في إسلام خالد بن الوليد بعد كم شهر فقط\nدلوقتي رسول الله ﷺ ممكن يقاتل فرقة خالد وينتصر عليهم بسهولة لأنهم ألف وأربعمائة وفرقة خالد مائتين فقط،\nلكن رسول الله ﷺ مش جاي لقتال أصلا،\n فاختار إنه يشوف طريق تاني يمشي منه عشان يتجنب المواجهة مع خالد، وده يديهم دليل أكبر إنه مش جاي لقتال، فبعد ما خلصوا الصلاة قال رسول الله ﷺ : \nمن فيكم يقدر يخرج بنا من المكان ده ويوصلنا لمكة من طريق تاني؟\nفمشى بهم رجل من قبيلة أسلم في طريق وَعِر صعب لحد ما وصلوا منطقة اسمها الحُدَيْبِية، لما خالد شاف رسول الله ﷺ والصحابة اتحركوا وغيروا طريقهم،\nرجع بالفرقة إللي معاه وانضم لجيش مكة إللي كان قريب من منطقة الحديبية،\nوالحديبية منطقة غرب مكة قريبة من البيت الحرام، اتسمت بالحديبية نسبة لشجرة حدباء كانت موجودة هناك، \nالمهم رسول الله ﷺ لما وصل لمنطقة الحديبية الناقة بتاعته بَرَكت لوحدها، يعني قعدت في الأرض، \nفالصحابة حاولوا يقوموها مش راضية تقوم فقالوا : خَلَأَتِ القَصْوَاء \nيعني القصواء وهي ناقة رسول الله ﷺ عصت رسول الله ﷺ وقعدت بدون إذنه،\nفرسول الله ﷺ قال: ما خلأت القصواء وما ينبغي لها، ولكن حبسها حابس الفيل\nفاكرين قصة فيل أبرهة\nيعني ناقة رسول الله ﷺ لم تعصِ أمره ولكنها أطاعت أمر من حبس الفيل عن هدم الكعبة، وهو الله\nفالله عز وجل أمر الناقة إنها تقعد في المكان ده ومتتحركش،\nلأن ربنا لا يريد لجيش المسلمين إنه يدخل فاتحا لمكة في الوقت ده، لسه ميعاد رجوع الصحابة لفتح مكة مجاش،\nوهنا كان رد فعل رسول الله ﷺ إنه قال:\nلا تدعوني قريش اليوم إلى خطة يعظّمون فيها حرمات الله   إلا أعطيتهم إياها\nيعني رسول الله ﷺ موافق إن يكون في صلح بينه وبين قريش،\nفقال للصحابة انزلوا وخيّموا في المنطقة دي،\nفقال له الصحابة المنطقة دي مفيهاش مية، فشاف رسول الله ﷺ بئر قديم فيه القليل من الماء فرمى فيه سهم فانفجر الماء بإذن الله وامتلأ البئر بمعجزة من الله عز وجل،\nرسول الله ﷺ قعد مستني يشوف إيه إللي هيحصل،\nقريش عرفت إن رسول الله ﷺ وصل لمنطقة الحديبية،  وممكن يحصل القتال في أي لحظة،\nعلى فكرة هم ميعرفوش إللي حصل مع القصواء وإن رسول الله ﷺ مش هيتحرك من مكانه خلاص، \nفهم متخيلين إن رسول الله ﷺ ممكن يدخل عليهم دلوقتي في أي لحظة\nلكن على الرغم من كل ده قريش مش عايزة تقاتل رسول الله ﷺ \nلأن إللي حصل خلال السنة السادسة من الهجرة من بعد الأحزاب وانتصارات المسلمين المتتالية كان له تأثير سلبي واضح على نفسية قريش وكانوا حاسين إنهم أضعف من المسلمين،\nفهم خايفين وفي نفس الوقت مش عايزين هيبتهم تروح وسط العرب وإن محمد ﷺ دخل مكة غصب عنهم،\nفأرسلوا واحد من قبيلة خُزاعة اسمه بُدَيْل بن وَرْقَاء الخزاعي عشان يتفاوض مع رسول الله ﷺ ويشوف هو جاي ليه فعلا ويحاول يمنعه من الدخول لمكة،\nوكانت قبيلة خزاعة حليفة لرسول الله ﷺ وكانت قريبة من قبيلة بني هاشم إللي منها رسول الله ﷺ،\nفقريش أرسلت واحد من القبيلة دي عشان يلطف الجو، ولم ترسل واحد من زعمائها عشان ميحصلش تهديد ووعيد وصدام والحرب تقوم بينهم\nرسول الله ﷺ عرف إن قريش موقفها ضعيف وإنهم مش عايزين قتال هم كمان،\nبديل بن ورقاء وكان مشرك قال لرسول الله ﷺ:\nأنا جايلك وسايب ورايا عمرو بن لؤي وكعب بن لؤي ومعاهم فرقتين من المقاتلين الأشداء وخرجوا ومعاهم نسائهم وأطفالهم،\nوهم مش هيسبوك تدخل البيت الحرام وهيقاتلوك\nطبعا الكلام مستفز\nوبُديل بن ورقاء بيهدد رسول الله ﷺ يمكن يخاف ويرجع وميدخلش مكة،\nتخيلوا بقى لو كان إللي جاء وقال الكلام ده أبو سفيان مثلا أو عكرمة بن أبي جهل \nكان رسول الله ﷺ هيقول لهم ماشي واحنا كمان مستعدين للقتال وتحصل حرب بينهم،\nلكن قريش كانوا عارفين بيعملوا إيه، أقصى حاجة لو كلام بُديل بن ورقاء استفز رسول الله ﷺ للقتال،\nقريش هتقوله: ده بُديْل من خزاعة مش من قريش واحنا ملناش دعوة بيه ومش موافقين على كلامه\nرسول الله ﷺ رد عليه بكل هدوء وبدأ يعرض عليه اقتراحات وقال:\n\"إنا لم نأتِ لقتال أحد، ولكن جئنا معتمرين، وإن قريشاً قد نَهِكَتْهم الحرب وأضرّت بهم، فإن شاءوا:\n◇مادَتُّهم مدة ويخلوا بيني وبين الناس.\n◇ وإن شاءوا أن يدخلوا فيما دخل فيه الناس فعلوا.\n◇ وإن أَبَوْا إلا القتال فوالذي نفسي بيده لأقاتلنهم على أمري هذا حتى تنفرد سالفتي أو ليُنْفِذن الله أمره.\nيعني احنا مجناش للقتال، احنا جئنا معتمرين، كل إللي احنا عايزين نعمله متوافق مع القانون بتاعكم،\nكل العرب من حقهم يعتمروا ويأتوا لبيت الله الحرام،\nاشمعنا احنا عايزين تمنعونا؟!!\nثم انت بتهددني بقريش وتقولي فرق عسكرية والكلام ده، أنا مش خايف أنا عارف كويس إن قريش بقت ضعيفة بسبب الحروب إللي دخلوا فيها ومش هيقدروا على حرب المسلمين وخصوصا بعد عودتهم من الأحزاب في خزي واضح \nولو هم عايزين ممكن يبقى في بيننا هدنة لمدة معينة ميكونش فيها قتال، ويسيبوني أدعوا الناس وهم كمان يدعوا الناس من غير ما يبقى في خوف من الدخول في حروب،\nورسول الله ﷺ عارف إن الدعوة في الجو السلمي بيكون أثرها وتأثيرها أكبر في القلوب عشان كده اقترح موضوع الهدنة،\nأو الاختيار الثاني وهو إنهم يدخلوا في الإسلام ويبقى لهم ما لنا وعليهم  ما علينا،\nأما لو أصروا على الحرب فأنا هفضل أقاتل حتى الموت، احنا لا بنخاف من القتال ولا الموت بالعكس ده احنا بنطلبه وبنحبه لأنه في سبيل الله،\nبْديل بن ورْقاء قال لرسول الله ﷺ إنه هيبلغ قريش رسالته،\nرجع بديل وقعد مع سادات مكة وقال لهم رسالة رسول الله ﷺ وبلغهم اقتراحاته الثلاثة،\nياترى كان رد فعل قريش إيه، ده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 135, "l": "الجزء 109 | احداث السنه السادسه من الهجرة | الاحداث في ارض الحديبية", "u": "", "t": "ليس المؤمن بالطّعان ولا اللّعان ولا الفاحش ولا البَذِيء\"\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وتسعة\n#أحداث_السنة_السادسة_من_الهجرة\n#ألأحداث_في_أرض_الحديبية\nوقفنا المرة إللي فاتت عند عودة بُديل بن ورقاء الخزاعي لقريش وإخبارهم برسالة رسول الله ﷺ إليهم،\nالمتوقع إنهم كانوا يثوروا ويغضبوا إزاي رسول الله ﷺ يقول لهم الكلام ده، \nلكنهم خافوا من رسول الله ﷺ، حسوا إنهم واقفين قصاد واحد مش فارقة معاه الحياة وحسوا بالضعف، \nونصحهم بُديل بن ورقاء إنهم يتركوا رسول الله ﷺ يدخل مكة يعمل العمرة،\nلكن قريش مش عايزين يسمحوا لرسول الله ﷺ ولا الصحابة إنهم يدخلوا مكة فمعجبتهمش نصيحة بديل بن ورقاء،\nوفي نفس الوقت هم لسه مش عايزين قتال، فإزاي يحققوا المعادلة الصعبة دي\nقرروا إنهم يرسلوا واحد تاني يتكلم مع رسول الله ﷺ، وبرده لم يختاروا واحد من ساداتهم عشان ميحصلش صِدام والأمور تتأزم أكثر،\nأرسلوا الحُلَيس بن عَلْقَمة، والحليس بن علقمة كان من بني الحارث بن عبد مناف بن كنانة زعيم الأحابيش إللي كانوا محالفين لقريش، \nفلما شافه رسول الله ﷺ جاي قال :\n\"هذا من قومٍ يُعظّمُون البُدْن\"\nيعني هو من قوم متدينين يحترموا قوانين وأعراف البيت الحرام ، وبيحترموا إللي ييجي لأداء العمرة أو الحج،\nفقال رسول الله ﷺ لأصحابه: سُوقوا الهَدْي أمامه \nيعني خلوه يشوف الإبل إللي جايبينها عشان يذبحوها قربة لله عن البيت الحرام،\nفالصحابة أرسلوا الإبل في وجه الحليس بن علقمة وقعدوا يلبوا : لبيك اللهم لبيك...\nابن علقمة شاف المنظر فقال: \nسبحان الله \nالناس دي مينفعش حد يصدهم ويمنعهم عن بيت الله\n☆رسول الله ﷺ استطاع إنه يكسب قلب الحليس بن علقمة حتى قبل ما يكون في بينهم أي كلام، \nيعني رسول الله ﷺ كان بيعامل كل واحد على حسب عقليته، لأن كل واحد له طريقة تعامل مختلفة حتى لو كان كافر،\nما هو الكفار أنواع، في كافر غادر وفي كافر لا يُعظم أي دين وفي كافر يعظّم دينه حتى لو كان دينه ده باطل،\nفرسول الله ﷺ استغل تعظيم ابن علقمة لدينه عشان يكسبه في صفه،\nورجع الحُلَيس بن علقمة لقريش وقال لهم:\nاسمحوا لهم بالدخول إلى مكة لأداء العمرة، ما ينبغي لهؤلاء أن يصدوا عن البيت\nلكن قريشاً طبعا معجبهمش الكلام وقالوا: \nالكلام ده مش هينفع معانا، احنا مش عايزينه يدخل البيت بأي طريقة\nفي الوقت ده كان في واحد بيزور مكة وهو عُرْوَة بن مسعود الثّقَفي سيد الطائف، وعروة بن مسعود ده هو تاني أعظم رجل عند العرب،\nفاكرين في الجزء الخامس عشر لما رسول الله ﷺ بدأ يدعوا قريش في البداية خالص وقالوا الكلام حلو بس ليه نزل على  واحد فقير ضعيف زي محمد ﷺ،\nوقالوا لو كان أُنزل على رجل من القريتين عظيم كان يبقى أحسن،\n\"وَقَالُوا لَوْلَا نُزِّلَ هَٰذَا الْقُرْآنُ عَلَىٰ رَجُلٍ مِّنَ الْقَرْيَتَيْنِ عَظِيمٍ \"\nوالمقصود بالقريتين هما مكة والطائف، والرجلين هما:\n الوليد بن المغيرة من مكة وعروة بن مسعود الثقفي في الطائف،\nفالرجل العظيم ده كان في مكة وسمع الحوار كله وسمع رسالة رسول الله ﷺ إللي جاء بها بُديل بن ورقاء، وسمع شهادة الحليس بن علقمة،\nفلما لقى قريش محتارة تعمل إيه، قال لهم:\nألست منكم بمنزلة الولد؟ قالوا: بلى،\nقال: ألستم مني بمنزلة الوالد؟ قالوا: بلى! \nفقال: طيب انتم ممكن تشكوا في ولائي لكم؟\nفقالوا له : لا\nفقال:خلاص خلوني أروح له واتكلم معاه،\nوالعرض إللي عرضه عليكم عرض كويس ومعقول فاقبلوه، وأنا ممكن لو اتكلمت معاه يعرض علىّ حاجة معرضهاش على بُديل وأقدر أحل الأزمة\nوطبعا لو عروة بن مسعود الثقفي استطاع إنه يحل المشكلة دي هيكون له فضل على قريش ومكانته هتبقى أكبر عند العرب، والناس في الزمن ده كانوا بيدوروا على المصالح الشخصية وعلى مكانتهم بين الناس،\nوهو قالهم أنا بمنزلة الولد لأن أم عروة بن مسعود كانت من قريش، فهو بيأكد لهم إنه حريص على مصلحتهم وإنه مش هيخدعهم ولا هيخونهم، \nفقريش وافقت إن عروة يروح يتفاوض مع رسول الله ﷺ،\nذهب عروة بن مسعود لرسول الله ﷺ وبدأ يكلمه، سأله في الأول: انت جاي مكة تعمل إيه\n☆طبعا رسول الله ﷺ واخد باله إن قريش متوترة وقلقانة، يعني أرسلت له ثلاثة رجال مش من قريش، يعني هو مفيش واحد من قريش يقدر ييجي يتفاوض معاه\nأكيد الموضوع في إنّ وهم خايفين وموقفهم ضعيف، عشان كده رسول الله ﷺ كان بيتكلم بكل هدوء وثبات،\nمع إن من الناحية العسكرية أهل مكة في موضع قوة، عندهم الجيوش وسلاح المحارب وعندهم الأكل والشرب،\nورسول الله ﷺ جاي من بعيد ومش معاه غير سلاح المسافر، لكن إللي فرق هنا إن رسول الله ﷺ والصحابة قوتهم الإيمانية عالية جدا\nرد رسول الله ﷺ على عروة وقال:\nأنا جاي أعمل عمرة وقريش ضعيفة دلوقتي ومش مستعدة للحرب، وأنا هعرض عليكم مدة نعمل معاهدة وميبقاش في حرب بيننا فترة من الزمن، \nولو عايزين حرب أنا برده جاهز، الناس إللي معايا جاهزين يموتوا في سبيل الله\nيعني كلام رسول الله ﷺ لعروة كان تقريبا نفس الكلام إللي قاله لبُديل بن ورقاء،\nفرد عليه عُروة وقال:\n\"أَيْ مُحَمَّدُ أَرَأَيْتَ إِنْ اسْتَأْصَلْتَ أَمْرَ قَوْمِكَ هَلْ سَمِعْتَ بِأَحَدٍ مِنْ الْعَرَبِ اجْتَاحَ أَهْلَهُ\"\nيعني بيقول لرسول الله ﷺ انت دلوقتي داخل ومعاك ألف وأربعمائة والقرشيين مش عايزين يدخلّوك وهيمنعوك عسكريا وانت هتحاربهم، \nهل سمعت إن حد من العرب قبلك اجتاح قومه، يعني دول أهلك هتدخل تحارب أهلك وناسك،\nطبعا الكلام يعتبر منطقي إزاي رسول الله ﷺ هيدخل يحارب أهله،\nلكن هم مين أهله دول؟\nمش أهله دول إللي قعدوا يعذبوه وأصحابه ويقاتلوه خلال تسعة عشرة سنة فاتوا\nهو مين إللي قتل سمية وياسر إللي هم من قريش، مش أهل قريش نفسهم؟!\nهو عروة مكنش شايف إللي كان بيعمله أهل مكة في رسول الله ﷺ والصحابة خلال ثلاثة عشرة سنة في مكة؟!!\nمكنش واصل له المقاطعة والحصار الاقتصادي إللي قريش عملته على بني هاشم مدة ثلاث سنوات؟!\nده حتى لما تركوا مكة وراحوا الحبشة مسكتوش وبعتوا عمرو بن العاص يرجعهم\nهو مين خلى رسول الله ﷺ والصحابة يسيبوا بلدهم ويسيبوا أموالهم وحياتهم ويروحوا بلد تانية خالص معندهمش أي حاجة فيها ويبقوا لاجئين إذا صح التعبير يعني\nهو إيه تزييف التاريخ ده\nده لسه السنة إللي فاتت بس قريش كانت جاية ومعاها عشرة آلاف عشان تجتاح المدينة وتُبيد المسلمين،\nهو مين إللي بيَجْتاح ويهجم عالتاني دلوقتي\nكل ده مكنش شايفه عروة بن مسعود\nللأسف هي دي عادة الناس إلا من رحم الله، عادي جدا يعملوا نفسهم مش شايفين الغلط إللي بيحصل ووقت ما نرد عشان ناخد حقنا يجيبوا الغلط علينا،\nالمفروض بقى إن رسول الله ﷺ والصحابة يتعمل فيهم كل ده ظلما وعدوانا، ومجرد ما يطلبوا حق من حقوقهم زي باقي الناس يبقى هم وحشين وبيعتدوا على قومهم المساكين\nنوعية الناس دي موجودة لحد دلوقتي وهتفضل موجودة،\nلأن طول ما في حق لازم هيكون قصاده باطل\nوإللي يغيظ بقى إنه ألغى العرض السلمي إللي رسول الله ﷺ عرضه\nيعني رسول الله ﷺ قال له ممكن نوقف الحرب ويبقى في هدنة، ولو قريش هي إللي عايزة القتال هنقاتلهم، \nفعروة أخذ النص التاني بقى وخلاص وضع رسول الله ﷺ موضع التهمة وإنه جاي يقتل أهله وناسه ولا كأنه سمع موضوع الهدنة ده\nولا كأنه سمع إن رسول الله ﷺ جاي يعمل عمرة، يعني هطوف بالكعبة وهمشي، فين الاجتياح والقتال هنا طيب\nلأ وهو نفسه من الطائف وعارف كويس أهل الطائف عملوا إيه مع رسول الله ﷺ لما راح يدعوهم وتعديهم عليه بالسب والقذف وضربه بالحجارة وطرده من المدينة\nوجاي دلوقتي يتكلم عن الأخلاق والقيم\n☆بجد الواحد مجرد ما بيفكر في الكلام بيحس إن دمه بيغلي، تخيلوا بقى إحساس رسول الله ﷺ والصحابة كان إيه وهم بيسمعوا كلام عروة واتهماته والافتراء عليهم بعد العذاب إللي شافوه السنين إللي فاتت دي كلها\nالمهم عروة بن مسعود كمل كلامه، وقال :\n\"وَإِنْ تَكُنِ الْأُخْرَى فَإِنِّي وَاللَّهِ لَأَرَى وُجُوهًا، وَإِنِّي لَأَرَى أَوْبًاشاً مِنْ النَّاس خَلِيقًًا أَنْ يَفِرُّوا وَيَدَعُوكَ\"\nيعني بيقول لرسول الله ﷺ لو بقى هم انتصروا عليك واتغلبت، فأنا مش شايف حولك ناس أشراف ولا ناس عظماء واقفين حواليك،\nده انت وسط ناس تعبانة مجمعهم من هنا ومن هنا، أول ما هيشوفوا إن في معركة هيهربوا ويسيبوك \n☆متخيلين إنه بيقول كده على الصحابة وهم قاعدين وسامعين\nالصحابة إللي مكنوش بيطيقوا إن رسول الله ﷺ يكون بس قاعد زعلان ولا تصيبه شوكه، والواحد منهم يفديه بروحه وبكل ما يملك، \nواحنا شوفنا الصحابة كانوا بيتعاملوا إزاي مع رسول الله ﷺ، بقى دول يهربوا ويسيبوه\nثم هو إيه إللي مفيش أشراف حوله ﷺ، أمال أبو بكر الصديق إللي كان مسؤول عن دفع الدّيّات عن قريش كلها قبل ما يُسلم كان إيه،\nوعمر بن الخطاب إللي كان مسؤول عن السفارات الخارجية لكل قريش قبل ما يسلم كان إيه، \nوفين طلحة بن عبيد الله والزبير بن العوام وعثمان بن عفان وأشراف الأنصار،\nكل دول مش أشراف في قومهم؟!!\nعظماء العرب واقفين حواليه وبيقول مش شايف ناس عِدلة \nكل ده ورسول الله ﷺ بيسمع بكل هدوء، مع إن الكلام كله كذب وافتراء وتدليس وشَتَم في الصحابة، \nبس رسول الله ﷺ مقطعهوش وسابه يتكلم ويقول كل إللي عنده،\nهنا واحد مُلَثّم يعني مغطي وجهه من المُلثّمِين إللي كانوا  قاعدين حول رسول الله ﷺ مقدرش يصبر أكثر من كده، عمال يسمع الكلام من الصبح وصابر بس خلاص مبقاش قادر يستحمل الكلام، رد على عروة بن مسعود وشتمه شتمة شنيعة جدا خلت عروة يتخض ويتصدم \nوبعد ما شتمه قال:\nأَنَحْنُ نَفِرُّ عَنْهُ وَنَدَعُه\n◇الصحابة كانوا مغطيين وجوههم وواقفين حول رسول الله ﷺ كنوع من الإرهاب وإظهار القوة والهيبة لرسول الله ﷺ، زي الحراس أو البودي جارد كده\nالمهم عروة لما اتشتم اتخض، متخيلين عظيم العرب في الوقت ده يتشتم ومش أي شتمة \nده أبو بكر أهانه إهانة شديدة مؤلمة للكافرين في الآلهة بتاعتهم\nفسأل وهو مصدوم وبينظر ناحية الشخص إللي شتمه : مين إللي شتم ده\nفقال : \nأنا أبو بكر!!\n☆أبو بكر\nأبو بكر أفضل من مشى على الأرض بعد الأنبياء،\nأبو بكر أكثر الصحابة صبر وحِلم...أبو بكر أكثر الصحابة رفقا ورقة، \nأبو بكر الرجل الأسيف كثير البكاء إللي هيُنادى عليه من أبواب الجنة الثمانية يدخل من أي باب أراد، \nأبو بكر الصديق إللي ربنا قال عنه سيجنبها الأتقى، يفقد أعصابه ويقول كلمة زي دي\nتخيلوا لما أبو بكر يكون ده رد فعله أمال باقي الصحابة زي عمر بن الخطاب مثلا كانوا حاسين بإيه والغضب كان جواهم أد إيه بسبب كلام عروة\n◇ملحوظة\nرسول الله ﷺ سمع الكلمة ومعقّبش وقال لأبي بكر مثلا مينفعش تقول كده أو أي حاجة تانية، لأ ده سكت،\nومعنى إن حاجة تحصل قصاد رسول الله ﷺ ويسكت فده معناه إيه بيُقِر الحاجة دي،\nلكن ده مش معناه إن رسول الله ﷺ بيُقر الكلام الفاحش ولا الشتيمة وهو القائل:\n\"ليس المؤمن بالطّعان ولا اللّعان ولا الفاحش ولا البَذِيء\"\nلكن في مواقف لازم يكون الرد فيها قوي وحازم وإلا الشخص هيتمادى في الغلط،\nوخصوصا إن الشخص ده كافر وتعدّى على الصحابة وكمان في وقت احتمال حرب، \nوالموقف هنا كان شديد جدا وحتى رسول الله ﷺ هيعمل حاجة مكنش بيسمح إنها تحصل في الأوقات العادية،\nومن هنا نتعلم إن في بعض الأوقات محتاجين نرد على بعض الناس بأسلوب شديد يخرسهم عشان نمنعهم من طغيانهم،\nزي ما الناس بتسميه دلوقتي قصف جبهة\nلكن ميكنش انتقام للنفس، أبو بكر رضي الله عنه لم ينتقم لنفسه، ده غضبه كان لله\nفالكلام ده يبقى في مواقف فاصلة، يعني أبو بكر الصديق رضي الله عنه معملش الكلام ده غير مرة واحدة بس في حياته،\nوغضبه كان لله ولرسوله وكمان كان في وقت احتمال فيه الحرب زي ما قلنا، فرسول الله ﷺ تجاوز عن الفعل ده من باب إرهاب المشركين،\nلكن الأصل إننا كمسلمين نتعامل بالأدب واللطف واللين وخصوصا مع المسلمين لأن ربنا قال :\n\"أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ\"\nالمهم عروة عارف أبو بكر وعارف شخصيته، فلما لقى أبو بكر الحليم رد عليه الرد ده، عرف إنه حط نفسه مشكلة\nفقرر إنه يعدي الموقف عشان الأوضاع متتأزمش وطلع منها بمخرج وقال لأبي بكر:\n\"أَمَا وَالَّذِي نَفْسِي بِيَدِهِ لَوْلَا يَد كَانَتْ لَكَ عِنْدِي لَمْ أَجْزِكَ بِهَا لَأَجَبْتُكَ\"\nيعني انت عملت معايا معروف قديم فمش هرد عليك الشتيمة جزاء المعروف ده،\nطبعا هو بيضيّع عشان يعدي الموقف لأنه عرف إن الصحابة غضبانين جدا دلوقتي\nوقعد يتكلم مع رسول الله ﷺ، وهو بيتكلم أمسك لحية رسول الله ﷺ، وكان العرب من عاداتهم لما واحد يحب يلاطف واحد وهو بيكلمه كان يمسك لحيته،\nفعروة مسك لحية رسول الله ﷺ على أساس إنه في نفس منزلته يعني كأنه واحد صاحبه وبيتودد له، ورسول الله ﷺ معترضش ولا منعه من باب تأليف قلبه حتى بعد الكلام إللي قاله،\nلما مسك لحية رسول الله ﷺ واحد تاني من المُلَثّمين إللي واقفين حول رسول الله ﷺ بظهر السيف راح ضارب عروة بن مسعود على إيده\nوقال: ابعد إيدك عن لحية رسول الله ﷺ\nفرفع رأسه ونظر للي ضربه وهو مصدوم، انت بتضرب عظيم العرب\nوسأل عروة بن مسعود : مين ده إللي ضربني\nفابتسم رسول الله ﷺ وقال لعروة:\nهذا ابن أخيك! المغيرة بن شعبة الثقفي\nطبعا عروة اتصدم صدمة شديدة جدا وقال: يا أيها الغادر! ده أنا عَمّك تعمل فيّ كده ،ده أنا لسه بجمع لك الدية لحد دلوقتي\n◇إيه قصته بقى\n قبل أن يُسلم المغيرة بن شعبة كان خرج مع ثلاثة عشر رجلا من ثقيف من بني مالك، \nفسهر معاهم واستناهم لما ناموا وغدر بهم وقتلهم كلهم وأخذ أموالهم وهاجر إلى رسول الله ﷺ في المدينة وأسلم،\nفقبل منه رسول الله ﷺ الإسلام أما المال فرفضه لأنه أُخذ غدرا، وفي شريعة الإسلام مينفعش أخذ المال غدر سواء كان مسلم أو كافر،\nفأموال الكفار تكون حلال بالمحاربة والمُغالبة، غير كده لأ\nفلعل رسول الله ﷺ ترك المال مع المغيرة عشان لو أسلم قومه يرجع لهم المال ولم يأخذه،\nحصل مشاكل بقى بين قوم المغيرة وبين بني مالك وكانوا هيقتتلوا، فعشان ميحصلش قتال عروة بن مسعود قال إنه هيدفع الدِّية،\nوقعد يجمع دية الثلاثة عشر رجل دول، فهو هنا بيقوله إنه لسه لحد دلوقتي بيجمع الدية عشان يصلح غلطته، وفي الآخر جزاؤه يكون إنه يضربه بالسيف.\n☆عروة بن مسعود ميعرفش حاجة عن الإسلام، ولا يعرف إن رسول الله ﷺ هو أغلى عندهم من أي حد مهما كان، وطبعا الرسالة وصلت واضحة لعروة بن مسعود، يعني أنا حاولت بس أمسك لحيته ضربتوني أمال لو قاتلته هتعملوا فيّ إيه؟ هتاكلوني\nعروة بن مسعود بعد ما شاف الموقفين دول من أبي بكر أحلم الناس، والمغيرة بن أخوه قعد ساكت وبدأ يراقب تصرفات الصحابة وهو مندهش من إللي بيعملوه،\nرجع عروة لقريش وسألوه عمل إيه، فقال لهم:\nوالله أنا زرت وشوفت الملوك، شوفت قيصر الروم في ملكه، وشوف كسرى في ملكه وشوفت النجاشي في ملكه،\n☆ودول أعظم ملوك الأرض في الزمن ده\nلكن والله ما شفت ملك بيعظمه أصحابه زي ما أصحاب محمد بيعظموه\nوالله ما تنَخّم نُخامة إلا وقعت في كف رجل فدلك بها وجهه وجلده\n☆انتم عارفين النخامة إللي بتخرج من الفم أو الأنف، في العادة الواحد بيستقذرها،\nالصحابة بقى مكنوش بيخلوا النخامة دي تقع في الأرض أصلا، كان الواحد منهم ياخدها ويدعك بها وجهه وجسمه،\nيعني الطبيعي إن الواحد بيقرف،\n لكن مع رسول الله ﷺ السلوك كان خارج عن الفطرة البشرية إللي عند أي إنسان\nفالبنسبة لعروة المشهد ده غير طبيعي بالمرة\nخدوا بالكم إن ده رسول الله ﷺ،  يعني مثلا عرقه كان ريحته ريحة المسك، فالحاجات دي كانت خاصة برسول الله ﷺ فقط، يعني لا يجوز التبرّك بأي إنسان تاني غير رسول الله ﷺ،\nوخدوا بالكم إن الصحابة مكنوش بيعملوا كده في كل حياتهم، \nورسول الله ﷺ مكنش بيسمح لهم أصلا بأقل من كده، يعني كان بينهاهم حتى عن مدحه ﷺ أو إنهم يقوموا يقفوا له،\nلكن هنا الموقف مختلف، \nهو سمح بالكلام ده عشان يُورّي عروة بن مسعود الناس إللي هو قال عنهم هيسبوه ويهربوا دول عاملين إزاي،\nيعني كأن رسول الله ﷺ بيقول له: الجواب هو ما ترى لا ما تسمع \nأكمل عروة وقال :\nولو وقعت منه شعرة كانوا بياخدوها، ولو أمرهم كل الناس تجري على طول عشان ينفذوا أمره، \nولو توضأ اقتتلوا على وضوئه، يعني بيتخانقوا على مين إللي يلحق ياخد المية إللي بتنقط منه، \nولو اتكلم يسكتوا والكل يسمع، ومش بيبصوا له في عينيه وبيبصوا في الأرض تعظيما له\nوهو عرض عليكم خطة رُشْد فاقبلوها، انتم مش أدّهم، لو قاتلتموهم مش هيستسلموا، وكلهم هيفنوا حياتهم قبل ما حتى توصلوا لمحمد \nياترى رد فعل قريش كان إيه، هل استجابت لكلام عروة بن مسعود الثقفي ولا لسه ناوية تبعت حد تاني\nده إللي هنعرفه الجزء الجاي إن شاء الله \n♡عروة بن مسعود الثقفي أسلم بعدين ومات شهيد رضي الله وهنعرف قصة إسلامه واستشهاده لما ييجي وقتها إن شاء الله"}, {"n": 136, "l": "الجزء 110 | احداث السنه السادسه من الهجرة | ارسال عثمان للتفاوض مع قريش", "u": "", "t": "اشاعة قتل عثمان بن عفان \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وعشرة\n#أحداث_السنة_السادسة_من_الهجرة\n#إرسال_عثمان_للتفاوض_مع_قريش\nاتكلمنا المرة إللي فاتت عن عروة بن مسعود الثقفي ولقائه مع رسول الله ﷺ وبعد اللقاء رجع لقريش وأخبرهم باللي شافه من أفعال الصحابة ونصح قريش إنهم يقبلوا بالعرض إللي رسول الله ﷺ عرضه عليهم،\nوالعرض كان إن يكون في بين قريش وبين المسلمين هُدنة،\nيكونوا فيها بعيد عن القتال وبعيد عن الحروب،\nوكان هدف رسول الله ﷺ من الهدنة دي إن الناس تسمع عن الإسلام في هدوء، لأن الجو المتوتر والمليان مشاحنات ومشاكل الناس مش بتعرف تفكر فيه وتسمع وتقرأ وبالتالي متعرفش توصل لقرار صحيح عن الدين،\nقريش لما سمعت كلام عروة خافت، وبدأو يفكروا فعلا في الصلح مع رسول الله ﷺ بس لسه مأخدوش القرار،\nمجموعة من الشباب المتحمسين المتهورين مش عاجبهم إن قريش بدأت تلين وتفكر في الصلح وتجر ناعم مع رسول الله ﷺ\nقام خمسين واحد من الشباب دول جامعين نفسهم وعلى رأسهم عكرمة بن أبي جهل وقالوا بلا مفاوضات بلا جدال بلا مناظرات بلا كلام فارغ\nوراحوا واخدين نفسهم وداخلين بالليل على معسكر المسلمين عايزين يقتلوا واحد ولّا اثنين،\nلما يقتلوا واحد من المسلمين هتولع الدنيا، ولما تولع الدنيا هتقف المفاوضات، يعني نظام بلطجية\nخدوا بالكم هم مش داخلين يقضوا على كل المسلمين ولا يحاربوهم ده المسلمين ألف وأربعمائة\nهم بس عايزين يشعلوا نار الفتنة بين الفريقين، ولسه هيهجموا على مجموعة من المسلمين راح محاوطهم محمد بن مسلمة بفرقة الحراسة إللي كانت معاه وكانوا مستخبيين في كمائن حول معسكر المسلمين بيحموهم،\nفأسروا الخمسين مشرك كلهم وذهبوا بهم لرسول الله ﷺ،\nطبعا ده كان في مصلحة رسول الله ﷺ وبكده يقدر يكسر قريش ويتفاوض عليهم، يعني هتسيبونا ندخل مكة ولّا نذبح الأسرى دول \nده غير الفضيحة بقى بين العرب يعني مجموعة من المقاتلين اتمسكوا في حركة غدر على المسلمين إللي جايين يعملوا عمرة،\nلكن رسول الله ﷺ عمل حاجة غير متوقعة، وهو إنه أطلق سراحهم منًّا بغير فداء، يعني سابهم يمشوا من غير أي مقابل خالص\nوده أكبر دليل لقريش إن رسول الله ﷺ مش عايز قتال وإنه جاي للعمرة وبس ومش عايز أي مشاكل،\nهو مش عايز يدخل مكة الآن مُقاتل، وتكثر الدماء ويبقى في بينه وبين أهل قريش الثارات والانتقام والجو يولع في الجزيرة العربية كلها،\nلأن لو رسول الله ﷺ فاوض على الخمسين دول وقريش ركبت دماغها وحاولوا ينقذوا الخمسين دول ممكن تقوم الحرب وهيبقى في قتلى من المشركين ومن المسلمين وتقوم الحرب وخُدوا بقى عشرين ثلاثين سنة على ما الأوضاع ترجع تهدأ في الجزيرة العربية\nرسول الله ﷺ مكنش عايز كله ده، هدفه أكبر من كده بكتير الموضوع مش مين إللي يثبت نفسه أو إنه ينتقم لشخصه، رسول الله ﷺ عايز ينشر الدين ويدخل الناس في الإسلام،\nفأطلق سراح الخمسين ورجعوا لقريش،\nوهنا قريش اتأكدت فعلا إن رسول الله ﷺ مش عايز حرب، دي مش عقلية مُحارب عايز يقتل ويذبح ويموّت،\nده فعلا مش جاي غير للعمرة وعايز يبقى في هدنة ومش بيخدعهم،\nفي نفس الوقت ده، رسول الله ﷺ شاف إن الموضوع طوّل أوي، وهم بعيد عن المدينة خمسمائة كيلو وكل شوية واحد جاي من قبيلة شكل ومفيش أي تقدم وقريش لسه مأخدتش أي خطوة لتنفيذ الهدنة،\nعايزين حد نقدر نكلمه نخلص معاه الموضوع مش كل شوية ييجي وسيط من قبيلة تانية\nفقرر إنه يرسل لهم واحد من أصحابه عشان يوضح لقريش قصده ويقوم بالمفاوضات إللي رسول الله ﷺ عايزها،\nلأن ممكن يكون الثلاثة إللي جاءوا دول موصلوش لقريش الرسالة إللي رسول الله ﷺ عايزها توصل بالضبط،\nعشان كده قريش اتأخرت في الرد\nفاختار رسول الله ﷺ واحد من الصحابة اسمه خِرَاش بن أمية من بني خُزاعة،\nركب الجمل بتاعه وتوجه لمكة عشان يبلغهم رسالة رسول الله ﷺ، أول ما دخل مكة اجتمع عليه السفهاء وقطعوا رجل الجمل بتاعه وسقط خراش واجتمع عليه السفهاء بالسيوف عايزين يقتلوه فلحقه الأحابيش وأنقذوه وأجاروه ورجّعوه لمعسكر المسلمين،\nحكى خِراش لرسول الله ﷺ إللي حصل معاه، طبعا الموقف ده كفيل إنه يشعل نار الحرب بين المسلمين وبين أهل مكة ويبقوا هم إللي غلطانين،\nلكن رسول الله ﷺ قرر إنه يعيد المحاولة ويشوف حد تاني يقدر يوصل الرسالة لقريش،\n☆خدوا بالكم يا جماعة رسول الله ﷺ مش حريص على الهدنة وعدم القتال لأنه ضعيف\nالصحابة لو دخلوا مكة هيكتسحوها وهينتصروا انتصار عظيم على أهل مكة، لكن هو مش عايز كده ﷺ هو حريص على إدخال الناس في الدين أكثر من إنه يقتلهم.\nفكر رسول الله ﷺ في رجل ثاني، اختار عمر بن الخطاب رضي الله عنه، يعني انتم اتعديتم على خِراش بن أمية طيب انا هبعت لكم عمر بن الخطاب\nواحنا عارفين إن عمر رجل قوي ومعروف بقوته في قريش فممكن يعمل شيء من الرهبة عند قريش،\nوكان عنده حكمة ورأي سديد وشوفنا إن القرآن نزل موافقا لرأي عمر في قضايا كثيرة زي إللي حصل في أسرى بدر و زي قصة تحريم الخمر وقصة الحجاب،\nورسول الله ﷺ يقول : \"لو كانَ بعدِي نبِيّ لكان عمر\"\nوكمان عمر كان سفير قريش في الجاهلية قبل الإسلام يعني لما يكونوا عايزين يتفاوضوا مع أي قبيلة كانوا بيرسلوا عمر، يعني هو مُفاوض ممتاز عنده القدرة على الحوار والجدال والمناظرة ،  \nوعنده ذكاء و علم واسع جدا وعارف حدود المفاوضات ويقدر ياخد قرار وهو قاعد هناك من غير يقع في خطأ شرعي، \nيعني بكل المقاييس هو الشخص المناسب للمهمة دي،\nلكن لما أخبره رسول الله ﷺ بإنه يروح يتفاوض مع قريش، عمر بن الخطاب رضي الله عنه رفض وده على غير عادته\nووضح سبب رفضه لرسول الله ﷺ وقال:\nيا رسول الله! ليس لي بمكة أحد من بني عدي يمنعني إن أوذيت\"\nيعني عمر بيتكلم بواقعية بيقول لرسول الله ﷺ أنا من قبيلة ضعيفة، قبيلة بني عدي،\nوهي بطن ضعيف من بطون قريش، لو حصل وحد جاء ليقتل عمر محدش هيدافع عنه، وعمر بن الخطاب مكنش خايف من القتل يا جماعة، ده عمر\nلكن هو عايز رسالة رسول الله ﷺ توصل ومعندوش أي مشكلة إنه يموت في سبيل الله ،\nلكن هو عايز المهمة تتم وشايف إنه مش هيقدر يتمم المهمة دي، وهو فاهم كويس أوي إن مش مهم مين إللي يوصل رسالة رسول الله ﷺ لكن المهم إن الرسالة توصل\nوبالمناسية هو لما اعتذر ورفض إنه يروح لقريش كان عارف إن ده مش وحي ولازم يتنفذ، هو عارف إنه كان مجرد رأي لرسول الله ﷺ قابل للنقاش والأخذ والرد،\nوانتم عارفين الوحي موجود وربنا عالم بالقلوب لو كان في قلب عمر حرص على نفسه أو إنه في قلبه شيء كان ربنا هينزل القرآن يوضح إللي في نفسه،\nفاقترح عمر على رسول الله ﷺ اقتراح أفضل من وجهة نظره إنه يرسل واحد له مَنعة في قومه ومن قبيلة قوية تقدر تدافع عنه ومحدش يقدر يتعرض له وميتقتلش،\nلأنه لو اتقتل كل شيء هيروح لا هيبقى في مفاوضات ولا صلح والحرب هتقوم ، فقال له:\n\"أرسل عثمان بن عفان فإن عشِيرَته بها وهو مُبَلّغ ما أردت\"\nيعني عمر بيقول لرسول الله ﷺ عثمان من قبيلة بني أمية وهي قبيلة قوية عزيزة شريفة لها تاريخ ولها جنود ولها رجال، والجميع بيعمل لها ألف حساب\nوكمان زعيم مكة أبو سفيان من قبيلة عثمان،\nفهو هيبلغهم إللي انت عايزه وهيحقق إللي أنا مش هقدر أحققه، ومخترش أبو بكر مثلا لأن برده ابو بكر من قبيلة ضعيفة مش هيقدروا يحموه،\nده غير كده عثمان بن عفان رضي الله عنه مشهور بالحلم والحكمة، فعنده القدرة على إنه يتفاوض ويؤدي المهمة بالضبط زي ما رسول الله ﷺ\nوكمان كان رجل محبوب جداً في داخل مكة سواء في أيام جاهليته أو في أيام إسلامه؛ لأنه كان كريماً واسع الكرم، وكل أهل مكة استفادوا منه قبل كده،\nوفوق كده هو زوج ابنتي رسول الله ﷺ، يعني كان متزوج في البداية من السيدة رقية ، فلما ماتت تزوج أم كلثوم ، فهو الآن زوج ابنة الرسول ﷺ ورسول الله ﷺ مش هيضحي بزوج بنته،\nفكده هيبقى واضح إنه رسول الله ﷺ عايز الصلح ومش عايز حرب،\nرسول الله ﷺ بكل بساطة وافق على اقتراح عمر بن الخطاب رضي الله عنه، لا في دكتاتورية ولا استبداد بالرأي ولا رأي متسلط،\nهو شاف إن اقتراح عمر هو الأنسب فرضي ووافق على رأيه.\n☆طب يعني هو رسول الله ﷺ مكنش يعرف كده\nرسول الله ﷺ بشر ممكن يخفى عليه أمور،\nفربنا كان بيعرفها له عن طريق الوحي، وأمور تانية يعرفها لرسول الله ﷺ عن طريق الشورى ،\nفكل الأحداث دي عشان نتعلم إزاي نتعامل مع المواقف في الحياة، بيعلمنا نسمع آراء إللي حوالينا وإننا ممكن نغير رأينا لو حد اقترح علينا اقتراح أفضل حتى لو مكانته أو منزلته أو علمه أقل\nفأخبر رسول الله ﷺ عثمان رضي الله عنه إنه يذهب لقريش ويتفاوض معاهم ويعرض عليهم خطة رسول الله ﷺ، يعني مش مطلوب إنه يعمل معاهدة هو بس مطلوب منه يوَصّل لزعماء قريش إللي رسول الله ﷺ عايزه،\nوعلى فكرة لو عثمان رضي الله عنه مكنش قوي ويُعتمد عليه مكنش رسول الله ﷺ خلاه هو المسؤول عن المفاوضات الخطيرة دي، ولو كان الاختيار غير صحيح كان نزل الوحي صحح الاختيار ده\nدخل عثمان بن عفان مكة وأول ما دخل طلع واحد من أقوياء بني أمية اسمه أَبَان بن سعيد بن العاص الأموي وقال:\n أنا أَجَرت عثمان\nوكان ساعتها أبَان لسه مشرك وهو ابن عم عثمان رضي الله عنه وكان يتميز إنه رحيم ولين وكان صاحب لعثمان من قبل الإسلام،\nفحصل زي ما عمر بن الخطاب رضي الله عنه كان متوقع،\nوده ترتيبنا احنا كبشر\nلكن ترتيب رب العالمين أعظم، لو الإنسان بذل الجهد إللي يقدر عليه هو يعطيه بزيادة سبحانه وتعالى\nشايفين أَبَان ده قدرا كده ومن غير ترتيب من أي حد خالص، قبل الأحداث دي بسنة أو سنتين كان في تجارة إلى الشام،\nوهو في التجارة دي قابل راهب نصراني فسأله عن رسول الله ﷺ وقال: \nأنا رجل من قريش وفي واحد خرج من بيننا بيدعي إنه رسول من عند الله أرسله زي ما أرسل موسى وعيسى، فإيه رأيك في الموضوع \nفقال له الراهب : ما اسم صاحِبِكُمْ؟ فقال له أبان :\nاسمه محمد، فقال الراهب: أنا هوصفه لك، فقعد الراهب يوصف له رسول الله ﷺ  وسنه ونسبه، \n\"أَوَلَمْ يَكُنْ لَهُمْ آيَةً أَنْ يَعْلَمَهُ عُلَمَاءُ بَنِي إِسْرَائِيلَ\"\nفقال أبان: هو فعلا زي ما بتقول\nفقال الراهب: والله، ليَظهرنَّ على العرب، ثم ليظهرنَّ على الأرْضِ\nوقال لأَبان: سلّم لي على الرجل الصالح ده\nرجع أبان لمكة وكلام الراهب في دماغه وبيفكر فيه وشايف صاحبه عثمان بن عفان صديقه القديم والرجل العاقل مُعتنق الدين ده وجاي يتكلم باسم الإسلام دلوقتي،\nفكل ده جعل أبان متحمس جدا وإنه يكون أول واحد يخرج للدفاع عن عثمان ويجعله تحت حمايته ولا كأنه واحد من المسلمين، \n\"وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ\"\nدخل عثمان في حماية سيوف بني أمية، وحتى زعيم مكة أبو سفيان كان من بني أمية زي ما قلنا، يعني كل الأمور مُيَسرة وتمام، \nقعد عثمان مع زعماء مكة وقال لهم بمنتهى الوضوح:\nاحنا جايين نعمل عمرة فقط ومش عايزين ندخل في حرب وده مش هدفنا إطلاقا\nعايزين واحد ييجي معانا ويقعد مع رسول الله ﷺ ونعمل مفاوضات سلمية ونوصل لحل يرضي الطرفين وخلاص،\nالموضوع مش مستاهل القلق إللي حاصل ده كله \nوبدأ عثمان يتحرك في مكة ويقابل الناس ويتعامل معاهم بلطف وقابل المسلمين المستضعفين إللي مخبيين إسلامهم وطمأنهم وصبرهم،\nفقريش لما شافت تصرفات عثمان بدأت تلين وعرضوا على عثمان إنه لو عايز يطوف بالبيت الحرام يطوف براحته عادي، يعني إكراما له وهو بقاله سنين مطفش بالبيت من ساعة ما هاجر،\nفقال لهم عثمان: ما كنت لأطوف قبل أن يطوف رسول الله ﷺ \nيعني أنا نفسي اطوف ومشتاق للطواف، لكن مستحيل أطوف قبل ما يطوف رسول الله ﷺ،\nمع إن رسول الله ﷺ مش شايفه ولا حتى هيعترض إنه طاف قبله، لكن حبه لرسول الله ﷺ منعه إنه يعمل حاجة رسول الله ﷺ نفسه يعملها هو كمان،\nالمهم حبسوا عثمان من إنه يرجع لرسول الله ﷺ، \nومش معنى إنهم حبسوه إنهم وضعوه في سجن\nلأ..هم قالوا له طيب خلينا نفكر ونتكلم تاني بكرة وبييجي بكرة يقولوا خلينا بعد بكرة ،\nلحد ما عدى ثلاثة أيام وعثمان في مكة وسادة قريش لسه مأخذوش قرار ورسول الله ﷺ كل ده ميعرفش حاجة عن عثمان رضي الله عنه،\nفي الثلاثة أيام دول طلعت إشاعة ووصلت لرسول الله ﷺ ومعسكر المسلمين، وهي إن عثمان رضي الله عنه قُتل، \nمكة قرية مقفولة حولها حراسة من الخارج الجيش الإسلامي بعيد عنها بعدة كيلو مترات،\nمفيش حد من المسلمين عارف يدخل ويتأكد من صح الخبر، وساعتها مكنش في لا اتصالات ولا في موبايلات ولا أي حاجة\nمنعرفش مين إللي سرّب الإشاعة دي، لكن الإشاعة وصلت لمعسكر المسلمين \nوكده بقى الموضوع كارثة، يعني رسول الله ﷺ صبر مرة واثنين وثلاثة وفي الآخر كمان تقتلوا رسولنا لأ معلش كده كفاية لازم ناخد موقف\nلأن ده مش موقف متعلق بشخص رسول الله ﷺ فممكن يسامح، ده أمر متعلق بالدولة الإسلامية ككل،\nجمع رسول الله ﷺ الصحابة الألف وأربعمائة وأمرهم إنهم يبايعوه، \nوكانت البيعة على إنهم لا يفروا أو بيعة حتى الموت، ومعنى إنهم لا يفروا يعني مهما حصل هيفضلوا في أرض المعركة حتى لو قُتلوا جميعا،\nوالبيعة دي من أعظم البيعات في تاريخ الأرض،\nعُرفت في التاريخ ببيعة الشجرة؛ لأنها تمت تحت شجرة عند الحديبية، أو بيعة الرضوان لأن الله عز وجل قال في القرآن أنه رضي عن الصحابة إللي بايعوا:\n\"لَّقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ \"\nطبعا كلهم بايعوا ما عدا واحد وهو الجَدّ بن قيس المنافق إللي قلنا إنه المنافق الوحيد إللي خرج مع رسول الله ﷺ، \nوكان بيستخبى من المسلمين وراء الجمال عشان ميبايعش،\nفهو برة الموضوع ده خالص،\nوقال رسول الله ﷺ:\n\"لن يدخل النار رجل شهد بدراً والحديبية\"\nكان أول مَن بايع من الصحابة سِنان بن أبي سِنان الأسدي، ابن أخ عُكّاشة بن محصن رضي الله عنهم أجمعين،\nوكان من أوائل الناس إللي بايعت رسول الله ﷺ  سَلمة بن الأكوع فاكرينه\nخير رجالتنا سلمة بن الأكوع\nبعد ما بايع راح قعد عند شجرة قريبة من رسول الله ﷺ، \nوأكمل الصحابة البيعة بعد شوية قال رسول الله ﷺ لسلمة :\nتعال بايع! \nفقال له : قد بايعت يا رسول الله\nفقال له: تعال بايع مرة ثانية فقام فبايع، وراح قعد في مكانه، وأكمل باقي الصحابة البيعة وفي الآخر ناداه رسول الله ﷺ وقال له تعال بايع،\nفقال سلمة لرسول الله ﷺ: بايعت أول الناس وأوسط الناس يا رسول الله \nفقال له رسول الله ﷺ: بايع مرة ثالثة، فبايع سلمة للمرة الثالثة وده لحرصه ﷺ على سلمة وأهمية وجود سلمة رضي الله عنه في الجيش، \nبعد ما انتهى رسول الله ﷺ من البيعة حط كفه إيده في إيده الثانية وقال : وهذه يدي عن عثمان\nلأن عثمان رضي الله عنه لو كان موجود كان بايع رسول الله ﷺ،\nفبايع رسول الله ﷺ نفسه بديلا عن عثمان، \nوخطب رسول الله ﷺ في الصحابة وقال لهم:\nأنتم اليوم خير أهل الأرض \nلسه رسول الله ﷺ والصحابة بيخططوا إزاي هيكون القتال لقوا عثمان بن عفان رضي الله عنه جاي،\nإيه إللي حصل بعد كده ، ده إللي هنعرفه الجزء الجاي إن شاء الله \n☆"}, {"n": 137, "l": "الجزء 111 | أحداث السنه السادسه من الهجرة | صلح الحديبية", "u": "", "t": "سهيل بن عمرو  بيقول لسيدنا محمد متكتبش بسم الله الرحمن الرحيم مين الرحمن دا متكتبش الرحمن ولا تكتب رسول الله \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وإحدى_عشر\n#أحداث_السنة_السادسة_من_الهجرة\n#صُلح_الحديبية\nوقفنا المرة إللي فاتت عند رجوع عثمان بن عفان رضي الله عنه لمعسكر المسلمين سالما بعد ما كانت طلعت إشاعة إنه قُتل،\nوبسبب الإشاعة دي بايع الصحابة بيعة الشجرة أو بيعة الرضوان، بعد ما رجع عثمان رضي الله عنه قعد مع رسول الله ﷺ يحكي له إللي حصل معاه،\nوكان وصل خبر بيعة الصحابة لقريش وخافوا وحصل لهم قلق، فبعد خروج عثمان من عندهم وتوجهه لمعسكر المسلمين قام واحد اسمه مِكْرز بن حفص من بني عامر بن لؤي من قريش وقال لهم :\nخلوني أروح أتفاوض مع محمد \nفقالوا له : ماشي روح له، \nوده كده أول واحد من قريش يخرج للمفاوضات، لكن مِكرز ده كان رجل شديد وعسكري معندوش أي نوع من الدبلوماسية ومش بيعرف يتفاوض،\nوقريش وافقت عليه عشان عايزين يلحقوا قبل ما الألف وأربعمائة يهجموا على قريش، يعني نوع من التعطيل لجيش المسلمين لحد ما يأخذوا القرار النهائي،\nرسول الله ﷺ لما شاف مِكرز جاي قال:\nمِكرز! هذا رجل فاجر أو هذا رجل غادر في رواية ثانية،\nرسول الله ﷺ عارفه وعارف تاريخه السيء مع المسلمين، كان من أكابر المشركين العنيفين جدا مع المسلمين\nرسول الله ﷺ برده عرض عليه نفس إللي عرضه على الوسطاء الثلاثة إللي قبله،\nوهم لسه بيتكلموا جاء سُهَيل بن عمرو، شافه رسول الله ﷺ وهو جاي فقال للصحابة : \nهذا سهيل بن عمرو! قد سَهُل أمركم!\nوكان رسول الله ﷺ يستبشر بالأسماء ويحب الفَأْل يعني الكلمة الطيبة، فاسم سهيل جاء من السهولة واليسر،\nوحتى سهيل بن عمرو نفسه حياته في مكة كانت حياة هادئة وهو شخص لطيف مكنش بينه وبين المسلمين مشاكل كبيرة زي أبو سفيان مثلا أو عكرمة بن أبي جهل\nفقال رسول الله ﷺ  للصحابة إن خلاص الأمور هتبقى سهلة يسيرة والمشكلة هتتحل،\nوطبعا احنا ملاحظين رسول الله ﷺ بيقرأ الشخصيات إزاي وبيعامل كل واحد على حسب شخصيته\nقعد سهيل مع رسول الله ﷺ وقال له :\nتعال نكتب بيننا كتابا، يعني هنتفاوض مع بعض على صلح يكون بيننا وإللي هنقوله هنكتبه ونمضي عليه،\nفأمر رسول الله ﷺ علي بن أبي طالب إنه يجيب حاجة يكتبوا عليها وكانوا بيكتبوا على الجلود، زي الورق عندنا كده.\n☆لما فريقين بيعملوا صُلح مع بعض ده معناه إن الفريقين دول عندهم قوة متكافئة يعني زي بعض تقريبا،\nفده اعتراف رسمي من قريش بقوة المسلمين\nماهو لو المسلمين ضعفاء مكنتش قريش أخدت القرار إنها تعمل معاهم معاهدة،\nيعني هل كان ممكن قريش ترضى بالصلح ده في السنة السادسة من البعثة، لأ..لأن ساعتها المسلمون كانوا ضعفاء فواضح دلوقتي الفرق الكبير بين المرحلتين\nبدأ رسول الله ﷺ بالكلام وقال لعلي:\nاكتب يا علي بسم الله الرحمن الرحيم!\nيعني لما بنبتدي بأي حاجة سواء كتابة أو أي عمل بنسمي الله، \nوحتى سليمان عليه السلام لما أرسل رسالته لملكة بلقيس أول حاجة كتبها كانت بسم الله الرحمن الرحيم فدي حاجة طبيعية،\nراح سهيل بن عمرو معترض، قال له : لا لا، هو مين الرحمن \nاحنا منعرفش الرحمن، الرحمن ده عندك انت مش عندنا، اكتب باسمك اللهم \nوكان المشركين بيقولوا إن في واحد اسمه الرحمن هو إللي بيعلم رسول الله ﷺ القرآن، وحتى ربنا قال عنهم:\n\"وَإِذَا قِيلَ لَهُمُ اسْجُدُوا لِلرَّحْمَٰنِ قَالُوا وَمَا الرَّحْمَٰنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًا \"\nوقال :\n\"وَهُمْ يَكْفُرُونَ بِالرَّحْمَٰنِ\"\nفمن أول كلمة بدأ الاعتراض\nفالصحابة اعترضوا وقال علي :\nلا والله، مش هنكتبها إلا بسم الله الرحمن الرحيم \nرسول الله ﷺ عارف إن قريش يكفرون بالرحمن وبينكروا صفات الله عز وجل ومنها الرحمن ماهو إللي نزل عليه القرآن وعارفهم وحافظهم ثلاثة عشرة سنة،\nفرسول الله ﷺ قال لعلي: \nاكتب باسمك اللهم\nرسول الله ﷺ عايز الأمور تمشي، مش وقته خالص إنه يقعد يديله درس في العقيدة ويقول له لأ ده فعلا صفة من صفات الله وهو الرحمن وهو الرحيم و...و...الكلام ده عندنا احنا في القرآن وهم مش مؤمنين بالقرآن،\nفخلينا نتفق دلوقتي على حاجة واحدة مشتركة بيننا ما دامت لا تتعارض مع ثوابت الدين\nوخدوا بالكم إن رسول الله ﷺ لم يلغِ صفة الرحمن أو يتنازل عن الصفة هو بس شاف إيه المشترك بينه وبين عدوه ووافق عليه\nفكتب علي رضي الله عنه باسمك اللهم، وأكمل رسول الله ﷺ في كلامه لعلي:\nهذا ما صالح عليه محمد رسول الله ولسه هيكمل الكلام راح سهيل معترض تاني وقال:\nمين محمد رسول الله\nماحنا لو كنا عارفين إنك رسول مكناش حاربناك أصلا\nاكتب اسمك واسم أبيك\n◇سهيل بن عمرو اعترض عشان لو اتكتب في المعاهدة رسول الله وبعدين مضى على المعاهدة، ده كده إقرار منه إن محمد ﷺ رسول من عند الله وهم أصلا مش مؤمنين به\nفقال له رسول الله ﷺ: والله إني لرسول الله وإن كذبتموني \nيعني أنا رسول الله وانتم كلكم عارفين إني رسول الله وربنا قال إنكم عارفين إني رسول من عنده:\n\"وَجَحَدُوا بِهَا وَاسْتَيْقَنَتْهَا أَنفُسُهُمْ ظُلْمًا وَعُلُوًّا ۚ فَانظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُفْسِدِينَ\"\nالمهم ،علي رضي الله عنه كان خلاص كتب الجملة إللي رسول الله ﷺ قالها له، فقال رسول الله لعلي: \nيا علي! امحُ رسول الله!\nيعني خلاص يا علي امسح كلمة رسول الله خلي المعاهدة تتم، \nرسول الله ﷺ عايز المعاهدة تتم وميكونش في مشاكل، عايز الناس تعيش في أمان ويسمعوا عن الإسلام في هدوء،\nوزي ما قلنا مادام الكلام لا يتعارض مع ثوابت الدين خلاص خلونا نقف على أرض مشتركة ونحل الموضوع.\n☆ الموقف عجيب فعلا ، رسول الله ﷺ عايز يعمل صلح مع قريش إللي قتلت أصحابة وعذبتهم وطردتهم من بلدهم وإللي بتحاربه بقالها سنين ولسه من سنة واحدة فقط كانوا جايبين الجيوش عشان يُبيدوا المسلمين،\nرسول الله ﷺ وهو بيكتب المعاهدة دي كان بيكتبها وهو عارف إن قريش أخذوا بيته بيت السيدة خديجة وباعوه وأخذوا ثمنه،\nومش هو بس ده معظم الصحابة إللي هاجروا حصل معاهم كده،\nومع كل الآلام دي كان حريص ﷺ إنه يتمم المعاهدة عشان المصلحة العامة للدين، مكنش بيفكر في نفسه ولا ساب مشاعره هي إللي تتحكم في الموقف،\nوفوق كل ده بيتعامل بلين عشان المفاوضات تمشي والحرب تقف، \nفقال رسول الله ﷺ لعلي امسح رسول الله واكتب محمد بن عبد الله،\nهنا علي مستحملش، قال لأ الموضوع كده مش نافع، يعني بسم الله الرحمن الرحيم عديناها وكتبنا باسمك اللهم،\nودلوقتي بيقول شيل رسول الله\nفقال علي لرسول الله ﷺ:\nلا والله يا رسول الله، لا أمحوك أبدا\nوبدأت تحصل مشكلة والصحابة وقفوا مع علي بن أبي طالب رضي الله عنه متفقين معاه.\n☆خدوا بالكم إن علي لم يعصِ أمر رسول الله ﷺ \nيعني أمر رسول الله ﷺ لعلي إنه يمسح اسمه مكنش على سبيل الإلزام، يعني الأوامر والنواهي بصفة عامة فيها ما يكون للإلزام يعني لاااازم يتنفذ،\nوفي ما لا يكون للإلزام، والشخص بيكون عارف امتى الكلام للإلزام وامتى بيكون فيه أخذ ورد،\nهنا علي رضي الله عنه استعظم إنه إزاي يمسح صفة الرسالة عن رسول الله ﷺ الصادق المصدوق، وهو فهم من رسول الله ﷺ إنه مش أمر إلزامي يجب عليه فعله،\nزي أمور الشورى كده، وزي موقف عمر إللي حكينا عنه المرة إللي فاتت لما رسول الله ﷺ كان عايزه يروح يبلغ رسالته لقريش وعمر رفض وقال له يرسل عثمان،\nفالأمر مكنش أمر إلزامي لعلي رضي الله عنه عشان كده اعترض\nرسول الله ﷺ بكل هدوء ومن غير مشاكل وخصوصا قصاد سهيل بن عمرو، مش هنتخانق قصاد العدو يعني قال لعلي:\nهي فين الكلمة؟\nرسول الله ﷺ كان أمّي مش بيعرف القراءة ولا الكتابة، فشاور له علي على الكلمة فمسحها رسول الله ﷺ بنفسه وخلاص أنهَى المشكلة\nوقال لعلي : اكتب محمد بن عبد الله!\nبدأ رسول الله ﷺ وسهيل بن عمرو يقولوا الطلبات بتاعة كل فريق، أول طلب رسول الله ﷺ طلبه من سهيل:\n◇ إنهم يتركوا رسول الله ﷺ والمسلمين يدخلوا مكة عشان يكملوا عمرتهم.\nسهيل بن عمرو رفض \nوده ثالث رفض أو اعتراض من سهيل بن عمرو، وبرر سبب رفضه وقال : لا يتحدث العرب أننا أُخِذنا ضغطا\nيعني عشان العرب ميتكلموش علينا ويعايرونا إننا اضغط علينا وقُهرِنا واتغلبنا ومحمد وأصحابه دخلوا غصب عننا، يعني مش عايز شكلهم يبقى وحش قصاد العرب،\nوأكمل سهيل بن عمرو كلامه وقال:\nلكن تدخل مكة العام القادم \nيعني بيطلب من رسول الله ﷺ إنه يرجع السنة دي وميكملش العمرة وييجي السنة الجاية يعتمر وهيدخلوه من غير أي مشاكل،\nولما تيجي تدخل مكة احنا هنسيبك تقعد في مكة ثلاثة أيام وأهل مكة هيفضّوا لك مكة بكاملها،\nيعني كل أهل مكة هيطلعوا برة مكة لما المسلمين يأتوا للعمرة، عشان ميحصلش احتكاك بين المسلمين والمشركين وتحصل مشكلة،\nوطبعا الاقتراح ده نصر عظيم للمسلمين، يعني هم كانوا جايين يعملوا عمرة في ساعتين وهيرجعوا، دلوقتي هيقعدوا ثلاثة أيام كاملة في مكة وكمان أهل مكة هيسيبوا مكة كلها للمسلمين ولما يمشوا هيرجعوا تاني،\nفوافق رسول الله ﷺ على الشرط الأول في صلح الحديبية.\n الصحابة سمعوا الكلام وشافوا رسول الله ﷺ وافق محدش منهم استطاع إنه يعترض، لكنهم كانوا متضايقين من جواهم ،إزاي يرجعوا من يغير ما يكملوا عمرتهم\n يعني الواحد لما بيجهز نفسه لمشوار أو سفرية يروح يتفسح فيها أو عايز يروح مكان بيحبه وفجأة المشوار ده يتلغي، وكمان يتلغي غصب عنه مع إنه ممكن يروحه تخيلوا بنبقى متضايقين إزاي\nالصحابة بقى سافروا خمسمائة كيلو في الصحراء على الجمال ورايحين متحمسين بعد ما رسول الله ﷺ أخبرهم عن الرؤيا إللي شافها وإنهم هيطوفوا بالبيت ،\nولما وصلوا اتعرضوا لضغوطات وكل ده متعشمين إنهم هيطوفوا بالبيت، وبعد كل ده هيرجعوا الخمسمائة كيلو دول تاني كده من غير ما يؤدوا العمرة،\nفكانوا متضايقين جدا بس ساكتين لأن خلاص رسول الله ﷺ موافق والموضوع يُعتبر فيه مصلحة لهم.\nسهيل بن عمرو طلب هو كمان طلب، الطلب الأول كان من رسول الله ﷺ فالطلب الثاني دلوقتي من سهيل قال:\n◇لو جاءك رجل من عندنا مسلم ترجعه لنا، ولو جاءنا رجل من عندك ترك الإسلام مش هنرجعه لك.\nيعني لو واحد من المشركين أسلم وحب يهاجر لرسول الله ﷺ يجب على رسول الله ﷺ إنه يرجعه تاني للمشركين،\nولو رسول الله ﷺ مرجعهوش وتركه يعيش في المدينة يبقى كده رسول الله ﷺ خالف المعاهدة، \nولو واحد ترك الإسلام ورجع للمشركين المشركين ميرجعهوش لرسول الله ﷺ.\n☆سهيل بن عمرو طلب الشرط ده من رسول الله ﷺ لأن كل شوية ناس تدخل في الإسلام وبيهاجروا وكده مكة هتفضى، ومن الناس إللي أسلمت أولاد سهيل الأربعة ثلاثة منهم هاجروا وإخوته كمان أسلموا وهاجروا،\nوابنه الرابع وكان اسمه أبو جندل الوحيد إللي معرفش يهاجر فكان سهيل بيعذبه عشان يسيب دينه وكان مقيده بالسلاسل في بيته عشان ميهربش،\nيعني تقريبا عائلة سهيل كلها أسلمت ماعدا هو، وكمان المسلمين قوتهم هتزيد فهو عايز يمنع الهجرة دي، عشان كده طلب من رسول الله ﷺ الشرط ده، \nوأهل مكة مش قادرين يمنعوا الناس من الدخول في الإسلام بالحجة والبرهان فملقوش قصادهم غير مبدأ القوة والغصب\nوكله بالقانون \nرسول الله ﷺ قاعد بيسمع كلام سهيل، الصحابة مقدروش يستحملوا الظلم ده فقالوا :\nسبحان الله، إيه إللي انت بتقوله ده\nإزاي يعني نرجع للمشركين واحد جاي لنا مسلم \nنرجعه لك وتقعد تعذبه ويُفتن في دينه، إزاي يعني\nرسول الله ﷺ لسه مقلش رأيه وهل احنا موافقين ولّا لأ، ولسه الشرط ده حتى لم يُكتب، والصحابة معترضين أصلا،\nوهم عمّالين بيتكلموا دخل عليهم أبو جندل بن سهيل بن عمرو والسلاسل والأغلال في إيده ورجله ورمى نفسه بين المسلمين\nأبو جندل لما سمع إن جيش المسلمين قريب وأبوه كان حبسه ومقيده بالسلاسل وكان بيعذبه؛ \nقعد يحاول ويحاول لحد ما عرف يفك نفسه من الأسر وكان في جنوب مكة والمسلمين كانوا في شمال مكة،\nففضل ماشي مسافة طويلة جدا وكل شوية يستخبى عشان محدش يشوفه ويرجعه للأسر والتعذيب مرة ثانية،\nوكله أمل إنه يوصل للمسلمين عشان يخلصوه من التعذيب إللي هو فيه ده\nوصل لمعسكر المسلمين أخيرا ورمى نفسه وسطهم وقال لهم الحقوني، طبعا منظره كان صعب القيود والسلاسل في إيده ورجله وهدومه مقطعة والتراب مغرقه وأثار التعذيب ظاهرة عليه،\nاحنا لو شوفنا واحد كافر بالمنظر ده هيصعب علينا وهنحاول نساعده،\nده بقى مسلم، واحد منهم جاي لهم بالمنظر ده، واحنا بنتكلم عن الصحابة إللي رسول الله ﷺ معلمهم انصر أخاك المظلوم، إللي معلمهم لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه، فتخيلوا مشاعرهم ساعتها عاملة إزاي\nوأبو جندل دخل على المسلمين في اللحظة إللي كانوا بيتكلموا فيها على الشرط بتاع إن إللي ييجي من مكة مسلم يجب على رسول الله ﷺ إنه يرجعه،\nرسول الله ﷺ شاف منظر أبو جندل فتأثر جدا وسهيل شاف التأثر ده في وجه رسول الله ﷺ فعرف إن رسول الله ﷺ هيحاول ياخد أبو جندل وينقذه فبسرعة راح قايل لرسول الله ﷺ:\nيا محمد هذا أول ما أقاضيك عليه\nيعني بيقول لرسول الله ﷺ ده أول واحد هطلب منك إنك ترجعه لمكة ومتقبلهوش وإلا مفيش معاهدة،\nفرسول الله ﷺ قال له:\nاحنا لسه مكتبناش الشرط ده ولسه متفقناش أصلا عليه!!\nفقال له سهيل: لأ، كتبنا مكتبناش لازم ترجع أبو جندل، \nولو مرجعتوش مش هيبقى في بينا معاهدة ولا هنكتب كتاب أصلا\nفرسول الله ﷺ قال: فأَجِزْهُ لِي!\nيعني رسول الله ﷺ بيقوله عديهولي، عشان خاطري يعني اعمله استثناء \nفقال سهيل : والله لا أُجِزْك أبداً \nيعني مستحيل أفوته، ده ابني إزاي أسيبهولك وانت واخد قبل كده ثلاثة، \nرسول الله ﷺ حاول معاه من هنا لهنا مفيش فايدة، سهيل مصمم إنه ياخد ابنه أبو جندل،\nهنا أبو جندل بدأ يتكلم: \nعايزين ترجعوني للمشركين يعذبوني ويفتنوني في ديني\nوالمسلمين نفسيتهم صعبة جدا\nموقف وراء الثاني وكل موقف أشد من إللي قبله وخلاص مش قادرين، ورسول الله ﷺ نفسه متضايق ومش عايز أبو جندل يرجع، هيتعذب ويُفتن.\n☆واضح جدا إن ده شرط سلبي في المعاهدة، ولو مضى المسلمون على المعاهدة دي هتبقى مشكلة كبيرة،\nلأن أي واحد عايز يسلم ويهاجر لرسول الله ﷺ رسول الله ﷺ هيرجعه تاني لمكة، \nوكده مكة بقت مطمئنة إن كل أهلها هيفضلوا مشركين طول مدة المعاهدة،\nالناس هتروح فين بعد كده، ده رافضه وده بيعذبه، فالناس كده مش هتسلم أصلا\nالموقف ده أو الشروط إللي زي كده بتعلمنا نقطة مهمة \nلما يكون في اتفاقيات أو مفاوضات بين المسلمين وبين طرف تاني قوته قريبة من قوة المسلمين وارد جدا إن الاتفاق ميكنش فيه كل المصلحة الكاملة للمسلمين،\nرسول الله ﷺ في الموقف ده بيعلمنا إننا لما نيجي نعمل مفاوضات مستحيل هيبقى المصلحة مائة بالمائة للمسلمين، الطرف إللي قصادنا هنديله حاجة وناخد منه حاجة،\nيعني في الصلح هنا الشرط ده فيه ظلم للمسلمين، والموضوع خطير، ده فتنة رجل في دينه،\nلكن احنا مش بنبص لمصلحة الأفراد ونتصرف على أساسها، احنا بندور على مصلحة الأمة كلها ،\nأيوة ابو جندل هيتعرض للإبتلاء وهنتنازل عنه في الوقت الحالي لكن في المقابل هيبقى في أعداد تانية كبيرة جدا هتدخل في الإسلام، \nفتنة أبو جندل في دينه وتعذيبه، ده ابتلاؤه يجب عليه إنه يتحمله ويصبر، \n\"أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا وَهُمْ لا يُفْتَنُونَ\"\nربنا مجعلش الدنيا من أولها لآخرها راحة وسعادة واطمئنان،\nبالعكس الإنسان حياته كلها مصاعب وابتلاءات،مش ربنا قال:\n\"لَقَدْ خَلَقْنَا الْإِنسَانَ فِي كَبَدٍ \"\nفالمصلحة العامة دلوقتي إن الصلح ده يتم عشان نقدر نتحرك براحتنا في الدعوة ونشر دين الله،\nوأبو جندل لما يتقِ ويصبر ومع صدقه وإخلاصه ربنا هيجعل له مخرج،\n\"وَمَنْ يَتَّقِ اللهَ يَجْعَلْ لَهُ مَخْرَجاً ۩ وَيَرْزُقْهُ مِنْ حَيْثُ لاَيَحْتَسِبُ \"\nوربنا هيحاسبه يوم القيامة هل ثبت في ابتلائه وصبر ولّا تنازل وترك الدين بسبب الابتلاء،\nالمهم،\nرسول الله ﷺ كان شايف الموقف وشايف فين المصلحة وفين المفسدة، المشكلة بقى إن أغلب الصحابة مكنوش شايفين رؤية رسول الله ﷺ دي، \nعشان كده كانوا في حالة غليان من الغضب والغيظ\nيا ترى كان إيه رد فعل الصحابة واتصرفوا مع الموقف الشديد ده إزاي،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 138, "l": "الجزء 112 | احداث السنه السادسه من الهجرة | فوائد من صلح الحديبيه", "u": "", "t": "الرسول أمر الصحابة إنهم يقوموا ويحلقوا رؤوسهم ويذبحوا الهدي ومحدش منهم قام، \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_واثني_عشر\n#أحداث_السنة_السادسة_من_الهجرة\n#فوائد_من_صلح_الحديبية\nاتكلمنا المرة إللي فاتت عن شروط صلح الحديبية واتكلمنا عن أبو جندل إللي جاء هارب من الأسر والتعذيب لمعسكر المسلمين وشوفنا محاولة رسول الله ﷺ إنه يضمه للمسلمين، \nلكن أبوه سهيل بن عمرو وإللي كان بيعمل المفاوضات مع رسول الله ﷺ رفض وصمم إنه يأخذه وإلا هيلغي الصلح بين المسلمين وبين قريش،\nوالصحابة عرفوا وفهموا من كلام رسول الله ﷺ إنه هيوافق على الشرط ده، لكنهم شايفين إن ده ظلم لهم فكانوا بيغلوا  من شدة الغضب والغيظ،\nيعني المفاوضات دي من أول كلمة اتغيرت مش عاجباهم وشايفين إن سهيل بن عمرو هو إللي بيُملي شروطه،\nظاهر الموضوع إنه عمال بيدي إملاءات واحنا بندي تنازلات،\nوهم مش ضعفاء،\nيعني لو رسول الله ﷺ أمرهم بالهجوم على مكة هيكتسحوا مكة ومحدش هيقدر يقف قصادهم\nكل ده كانوا صابرين ومستحملين لحد ما حصل موقف أبو جندل هنا خلاص وصلوا لمرحلة صعبة،\nالمشكلة إن محدش فيهم قادر يتكلم خايفين ينزل فيهم قرآن\nفهنا قام المُلهم عمر بن الخطاب، عمر بن الخطاب إللي وُزن إيمانه بإيمان الأمة بدون ما يكون فيها أبي بكر رجح إيمان عمر ،\nفهو الرجل الثالث في الدولة الإسلامية، قال لرسول الله ﷺ وتقريبا كل الصحابة كان جواهم الكلام ده:\nألستَ نبي الله حقًّا، قال له رسول الله ﷺ : «بلى»، \nقال عمر: ألَسنا على الحق، وعدوّنا على الباطل\nقال رسول الله ﷺ : «بلى»، \nقال: فَلِمَ نُعطِي الدّنيّة في ديننا إذن\nقال رسول الله ﷺ : \n«إني رسول الله، ولستُ أعصيه، وهو ناصري» \n☆إللي يسمع كلام عمر يستغرب\n هو ده سؤال يسأله بعد ما قعد في الإسلام ثلاثة عشرة عام وشاف المعجزات والقرآن بينزل، بيسأل رسول الله ﷺ هل انت فعلا نبي، واحنا على الحق؟!!\nهو سؤال عمر هنا الغرض منه التقرير،\nيعني عايز رسول الله ﷺ يُقره فعلا على المعنى ده،\nزي لما آجي أقول لبنتي أو ابني مثلا مش أنا قلت لك متتأخرش برة البيت، \nأنا عارف إجابة السؤال بس بأكد على المعنى، عشان لما يقولي أه قلتي، أقوم أسأله: طيب اتأخرت ليه، زي ما عمر سأل للإقرار، وبعدين سأل بقى السؤال المطلوب: \nليه احنا بقى نتنازل التنازلات دي كلها في ديننا،\nوالكلام كده معناه إن عمر رضي الله عنه بيتهم رسول الله ﷺ إنه بيُعطي الدنيّة، يعني بيفرط في قضايا دينية،\nوده رسول الله ﷺ \nأنا عايزاكم تتخيلوا مشاعر الغضب إللي كان واصل لها عمر في الوقت ده كانت عاملة إزاي لدرجة خلته يقول الكلام ده\nفكان رد رسول الله ﷺ إنه فكر عمر هو مين، وقال له أنا رسول الله، ومش ممكن هعصي ربنا، الله يرى المفاوضات والأحداث ولم ينزل وحي يقول عكس كلامي،\nوهو ناصري، يعني ياعمر إللي انت شايفه ده ومستغربه هيكون فيه النصر\nالمفروض إن عمر خلاص سمع الكلمتين دول يسكت بقى لأن هنا القضية قضية إيمان، لكن عمر مسكتش\nقال لرسول الله ﷺ: \nألستَ كنت تُحدثنا أنا سنأتي البيت فنطوف به\nانتم عارفين إن السبب أصلا في خروج المسلمين للعمرة هو الرؤية إللي رآها رسول الله ﷺ، فدلوقتي هيرجعوا من غير ما يعملوا العمرة، فين بقى الرؤية\nفقال له رسول الله ﷺ : \nبلى، فأخبرتك أنا نَأْتيه العام؟!!\nيعني أيوة أنا قلت لكم كده فعلا، بس هل أنا قلت إنكم هتعتمروا السنة دي؟!!\nفقال عمر: لا\nفقال رسول الله ﷺ : فإنك آتيه ومطوّف به\nيعني انت فعلا هتيجي تعمل عمرة وهتطوف بالبيت زي ما أنا قلت لكم، لكن متحاسبنيش على حاجة مقلتلكش عليها،\nرسول الله ﷺ بيتكلم مع عمر في حوار عقلي هادئ جدا، \nده احنا في تعاملتنا اليومية ممكن من أول كلمة نعمل مشكلة\nيعني رسول الله ﷺ مقلش لعمر يعني انت بتكذبني بعد السنين دي كلها، ما تسمع الكلام وخلاص، أو ملكش دعوة أصلا، هو بكل بساطة استمر معاه لآخر الحوار.\n☆والموقف ده كان بعيد عن سهيل بن عمرو، يعني كان إما بعد ما خلاص كتبوا المعاهدة، أو إن عمر أخذ رسول الله ﷺ   على جنب وكلمه،\nالمهم ،\nالطبيعي هنا بقى إن خلاص عمر يقتنع ويسكت بعد كلام رسول الله ﷺ له، لكن عمر لسه برده مش مقتنع وفي قلبه غضب\nفراح لأبي بكر الصديق رضي الله عنه ومكنش حاضر الموقف ده وميعرفش إللي حصل بين رسول الله ﷺ وبين عمر،\nقال عمر لأبي بكر:\nيا أبا بكر، أليس هذا نبي الله حقًّا؟ قال أبو بكر: بلى، \nقال عمر : ألسنا على الحق، وعدونا على الباطل؟ \nقال أبو بكر: بلى،\n قال عمر: فلم نُعطي الدنية في ديننا إذن؟ قال: أيها الرجل!!إنه لرسول الله ،وليس يعصي ربه، وهو ناصره، فاستمسك بغَرْزه، فوالله إنه على الحق\nفقال عمر : أليس كان يحدثنا أنا سنأتي البيت ونطوف به؟ \nقال: بلى، أفأخبرك أنك تأتيه العام؟ \nقال: لا، قال: فإنك آتيه ومطوّف به\nسبحان الله نفس الإجابة إللي رسول الله ﷺ قالها لعمر أبو بكر الصديق رضي الله عنه قالها هو كمان لعمر\nلأ وزود نصيحة مهمة جدا لعمر ولنا احنا كمان :\n 《فاسْتَمسِك بغَرْزِه》\nيعني شوف هو حط رجله فين وحط رجلك مطرح ماهو حطها، \nمشي من الطريق ده امشي وراه، مشي من الطريق الثاني\nامشي وراه حتى لو مش مقتنع حتى لو انت مش فاهم، \nأي طريق تاني هتضيع، وهو ده اتباع السنة\nهنا عمر رضي الله عنه عرف إنه أخطأ وإنه كان لازم يتحكم في نفسه، فخاف، وقعد يعمل أعمال صالحة كثيرة عشان يكفر عن الخطأ ده،\nوالخطأ ده كان عشان عايز ينصر الإسلام ومش عايز يكون الإسلام في موقف ضعف، \nومع ذلك قعد يعمل أعمال صالحة كثيرة، فما بالنا بقى باللي بيعترض على أحاديث رسول الله ﷺ وبيردها وإللي بينكرها أصلا ده محتاج يعمل إيه \nخلاص الشرط الثاني اتكتب وهو إن إللي يأتي من مكة مسلما يجب على رسول الله ﷺ إنه يرده، وإللي يأتي من عند رسول الله ﷺ وهو مرتد عن الإسلام أهل مكة لا يردوه،\nورجع ابو جندل لمعسكر المشركين وكملوا باقي الشروط، \n☆ملحوظة:\nأي حد يأتي من داخل مكة فقط هو إللي رسول الله ﷺ يرده، لكن أي واحد أسلم من أي مكان تاني لا يرده رسول الله ﷺ، يعني الشرط ده خاص بمن يُسلم من قريش، \nلكن لو أي واحد أسلم من أي قبيلة تانية وجاء مهاجر لرسول الله ﷺ، رسول الله ﷺ لا يرده لقريش،\nفاحنا دلوقتي ضحّينا بعدد معين من مسلمي قريش في مقابل إسلام ناس كثيرة جدا،\nوزي ما قلنا المرة إللي فاتت إن مصلحة الأمة كلها مقدمة على مصلحة الفرد الواحد\nوعلى فكرة هي مش تضحية أوي يعني\nلأن أبو جندل وإللي زيه أو أي حد ممكن يُسلم من قريش ممكن يهاجر لأي مكان تاني غير المدينة، زي الحبشة مثلا أو أي مكان هو عايزه،\nأو إنهم يتظاهروا بالكفر ويكتموا إيمانهم لحد ما الفرج يأتي،\nوبالعكس ممكن يخدموا الإسلام وهم في مكة بإنهم يعرّفوا رسول الله ﷺ بأخبار المشركين في مكة،\nيعني يبقى جاسوس للمسلمين داخل مكة، وبالنسبة بقى للي يترك المسلمين ويروح للكفار وقريش مترجعهوش للمسلمين فده كمان مصلحة، \nيعني واحد ارتد، أو منافق كان بيظهر الإيمان ويُبطن الكفر ده احنا هنحتاجه في إيه أصلا، لأ مش عايزينه\n \nده بالعكس لو واحد عايز يرتد هيخاف إنه يرتد عشان ميرجعش للمسلمين، وده مش في صالح المسلمين لأن المنافق أخطر على المسلمين من الكفار، \nواحنا شوفنا إللي حصل منهم في غزوة أُحد وفي حادثة الإفك وغيرها من المواقف، فقلّتهم أحسن\nوربنا قال عنهم :\n\"لَوْ خَرَجُوا فِيكُمْ مَا زَادُوكُمْ إِلا خَبَالا وَلأَوْضَعُوا خِلالَكُمْ يَبْغُونَكُمُ الْفِتْنَةَ\"\nنرجع لباقي الشروط،\n◇الشرط الثالث إللي اتفقوا عليه كان:\nإن الحرب تقف بين المسلمين وبين قريش عشر سنوات.\nطبعا الشرط ده في صالح المسلمين جدا، عشان يقدروا يأسسوا لدولتهم مضبوط من غير ما يخافوا من إن قريش تهجم عليهم في أي وقت\nوالدعوة والحركة هتكون أسهل، والناس لما تسمع عن الإسلام من غير تشويش وتعرفه معرفة صحيحة إللي فطرته سليمة هيقبل الإسلام بدون تردد،\nوالناس خايفين من قريش، فلما يطمنوا إن قريش مش هيعتدوا عليهم خلاص هيبقى سهل عليهم يدخلوا في الإسلام،\nفالمسلمين هم إللي محتاجين الهدنة دي أكثر من قريش.\n◇الشرط الرابع:\n إن إللي عايز يدخل في حِلف المسلمين من القبائل يدخل، وإللي عايز يدخل في حِلف قريش يدخل، \nوالقبيلة إللي هتدخل مع أي طرف بقت خلاص جزء من الفريق ده، لو تعدى عليها أي حد بقى الاعتداء على الطرف الأساسي في المعاهدة،\nيعني قبيلة خُزاعة دخلت مع المسلمين، وبني بَكر دخلوا مع قريش، فلو قريش أو بني بكر اعتدوا على خُزاعة يبقى كأنهم بالضبط اعتدوا على المسلمين ويبقى المعاهدة اتنقضت خلاص،\nوالشرط ده كمان كان في صالح المسلمين برده، لأن كل القبائل تقدر تدخل في حلف قريش، مش مستنيين يعني معاهدة زي كده عشان يتحالفوا معاها\nلكن إللي هيستفيد من الحلف ده هم المسلمين لأن القبائل تقدر تنضم للمسلمين بدون خوف من قريش زي قبيلة خزاعة،\nفقبيلة خزاعة على الرغم من قربها الشديد من بني هاشم ومن المسلمين مكنتش قادرة تساعد المسلمين ولا تدعمهم بسبب خوفها من قريش لكن دلوقتي خلاص مبقاش في خوف لأن بقى في معاهدة بينهم\n☆للأسف في ناس بتستغل صلح الحديبية ده وتقول عادي نعمل معاهدات مع المشركين والكفار عادي جدا ونقدم لهم تنازلات،\nأيوة احنا ممكن نعمل معاهدات مع غير المسلمين لكن بشرط إنها تكون زي ما رسول الله ﷺ عمل، صلح رسول الله ﷺ مع المشركين مكنش فيه:\n◇إقرار للمشركين على باطل ولا في أي تنازل عن ثوابت الدين، والصلح ده مش بيمنع المسلمين من إن يكون عندهم أحدث الأسلحة ولا بيأمرهم إنهم يغيروا مناهجهم التعليمية عشان يقعدوا يمجدوا في قريش\nوكمان المعاهدة ميكونش فيها تقييد للمسلمين في حرية الدعوة إلى الله وبيان الحق.\n◇والصلح ده مكنش فيه أي علاقة صداقة بين المسلمين وقريش، العداء إللي بينهم مستمر لأن ده عداء في العقيدة مينفعش فيه أي تنازل، كل الموضوع إن الحرب هتقف لكن العداء بينهم مستمر\n◇رسول الله ﷺ لما عمل المعاهدة دي كان المسلمون أقوياء، عشان لو قريش خالفت المعاهدة رسول الله ﷺ يقدر يرد عليهم بقوة،\nلكن لو المسلمين ضعفاء وقريش خالفت المعاهدة واعتدت عليهم إزاي المسلمين هيقدروا يجيبوا حقهم\nلكن للأسف دلوقتي المعاهدات إللي بتحصل بين المسلمين واليهود أو بين المسلمين وغيرهم بتتعمل والمسلمين ضعفاء وكل شوية يقدموا تنازلات عشان يرضوا عدوهم،\nويحصل عليهم اعتداءات ومش عارفين يردوا بسبب ضعفهم\n☆طيب احنا كأفراد نستفيد إيه من صلح الحديبية\n♡نستفيد إننا منقدمش أي تنازلات في ديننا، لكن نقدر نقف مع المخالف لنا على أرض مشتركة،\nيعني مادام في حل وسط بيني وبين شخص أنا متخانق معاه مثلا أو في بيني وبينه مشكلة\n《لا تمس أي تنازل في الدين》خلاص ممكن آخد بالحل ده عشان أحل المشكلة،\nمش لازم أحل المشكلة بطريقتي وزي ما أنا عايز بالضبط \nوإلا مش هحلها، زي ما رسول الله ﷺ عمل،\nهو قال بسم الله الرحمن الرحيم وسهيل قال باسمك اللهم،\nهو مشّاها باسمك اللهم لأنها حل وسط ومفيش تنازل\n◇مثال من حياتنا العملية:\nعندنا طفل وعارفين إنه عنيد ومش بيسمع الكلام وبيصمم على رأيه وبيعمل مشاكل،\nوأنا عايزه يعمل حاجة معينة، بدل ما أقوله قوم اعمل كذا حالا وسيب اللعب إللي في إيدك،\nممكن أقول له : إيه رأيك بعد ما تخلص اللعبة إللي في إيدك دي تقوم تعمل كذا؟ \nأنا وهو دلوقتي وقفنا على أرض مشتركة وهي إني إديته مجال يخلص لعبته وفي نفس الوقت أنا خدت إللي أنا عايزه، \nوهو ممكن يرفض على فكرة وساعتها بنفضل معاه في مفاوضات لحد ما نوصل لحل يرضي الطرفين،\nوكذلك برده الزوج مع زوجته والزوجة مع زوجها، مش لازم كل حاجة تمشي يا أبيض يا أسود مادام الأمور فيها مُتسع،\nأبيض واسود دي لما يكون حاجة فاصلة مفيهاش كلام\n♡ونتعلم برده من صلح الحديبية إننا ممكن نقدم تنازلات لو كان في مقابل التنازلات دي مصلحة أكبر بكثير من التنازل ده، وطبعا بيبقى على حسب كل موقف امتى فعلا ينفع نتنازل وامتى مينفعش،\nمثلا يعني زوج كان مسافر ورجع من السفر بعد غياب وزوجته وأولاده مستنيينه عشان يقعدوا معاه، \nفأم الزوج وأبوه عايزين يقعدوا مع ابنهم فراحوا قعدوا عنده في البيت مع زوجته وأولاده،\nطبعا هنا في مشكلة والزوجة هنا قصادها اختيارين :\nإما إنها تعترض وترفض وجود الأب والأم، وإن زوجها يبقى يروح يزورهم زيارات عادية،\nأو إنها تتنازل عن الكام يوم إللي هيقعدوهم معاهم وطبعا ده أكيد في ضغط وتعب عليها،\nلكن في المقابل أولا : \nراحتها النفسية من الشد والجذب والعصبية والخناق مع زوجها،\nثانيا: إنها تعين زوجها على بره بأمه وأبيه، \nثالثا: هي أم وممكن ييجي اليوم إللي هي نفسها تتحط في الموقف ده وساعتها هتبقى نفسها تقعد مع ابنها،\nوالجزاء من جنس العمل\nفالموقف ده في تنازل عن شيء احنا عايزينه، لكن في مصلحة أكبر في التنازل ده لمن يرى بعين الآخرة طبعا\n♡وكمان صلح الحديبية بيعلمنا التسليم لأوامر الله ورسوله حتى لو مش فاهمين الحكمة منها إيه، حتى لو مش مقتنعين وإن الاعتراض على أوامر رسول الله ﷺ ممكن يكون فيه الهلاك\n♡وصلح الحديبية من اسمه بيعلمنا الصلح، رسول الله ﷺ تصالح مع كفار قريش إللي ظلموه وآذوه وعذبوا وقتلوا أصحابه وأخرجوه من مكة وأخذوا بيته وحاربوه،\nفإيه المشكلة إننا كمسلمين نصلح ذات بيننا، كل واحد يحاول من طرفه إنه يصلح بينه وبين أي اثنين بينهم مشكلة،\nأو يصلّح المشاكل إللي بينه وبين الناس،\nربنا بيقول : \n\" فَاتَّقُوا اللَّهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ\"\nورسول الله ﷺ يقول : \nألا أخبركم بأفضل من درجة الصيام والصدقة والصلاة، فقال أبو الدرداء : \nقلنا بلى يا رسول الله ، قال : إصلاح ذات البين\"\nوفي آيات كثيرة وأحاديث عن إصلاح ذات البين والعفو،\nإن شاء الله هنتكلم عنها في وقتها على حسب المواقف إللي نزلت فيها\n☆صلح الحديبية فيه دروس وعبر كثيرة وأنا قلت لكم بعض النقط السريعة فقط\nكده خلاص انتهى صلح الحديبية وعلى حسب الشرط الأول فالمسلمين لازم يرجعوا للمدينة، فبدأ رسول الله ﷺ يتجهز للرجوع للمدينة، \nلكن هو لسه على إحرامه هو والصحابة فلازم يتحللوا من الإحرام بحلق الشعر وذبح الهَدْي، فقال لهم رسول الله ﷺ:\nقوموا فاحلقوا رؤوسكم وانحروا الهدي! \nفحصل موقف غريب جدا، وهو إن مفيش ولا واحد منهم   قام يعمل إللي رسول الله ﷺ قال عليه\nرسول الله ﷺ كرر عليهم :\nقوموا فاحلقوا رؤوسكم وانحروا الهدي! \nمحدش قام\nكرر عليهم للمرة الثالثة :\nقوموا فاحلقوا رؤوسكم وانحروا الهدي! \nبرده محدش قام\nفتركهم رسول الله ﷺ ودخل خيمته وكان فيها أم سلمة رضي الله عنها، \nفلما شافته عرفت من وجهه إنه متضايق وزعلان، فسألته عن إللي مضايقه، فحكى لها إنه أمر الصحابة إنهم يقوموا ويحلقوا رؤوسهم ويذبحوا الهدي ومحدش منهم قام، \nفقالت له:\nقم انت يا رسول الله اخرج ومتكلمش حد خالص لحد ما تذبح الهدي بتاعك ونادي على الحلّاق خليه يحلق لك، وهم لما يشوفوك عملت كده هيعملوا زيك\nخرج رسول الله ﷺ من الخيمة وأخذ بنصيحة زوجته أم سلمة رضي الله عنها وبدأ فعلا في نحر الهدي، \nالسؤال بقى هل الصحابة استجابوا فعلا لرسول الله ﷺ وبدأوا يعملوا زيه، ولا إيه إللي حصل\nده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
